window.PDD_DATA = window.PDD_DATA || [];
window.PDD_DATA = window.PDD_DATA.concat([{"num": 589, "text": "Неисправность, в которой компонент может привести к неравномерному или чрезмерному износу шин?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Акселератор.", "Муфта.", "Коробка передач.", "Подвеска."], "correct": 3, "expl": "Несправність підвіски (амортизаторів, важелів, розвалу-сходження) — найпоширеніша причина нерівномірного чи надмірного зносу протектора шин.", "explSpecific": "Правильно — «Подвеска». Акселератор, зчеплення чи коробка передач не мають прямого механічного впливу на контакт шини з дорогою."}, {"num": 590, "text": "Есть ли случаи, когда водитель-ученик может водить автомобиль без сопровождения?", "topic": "Штрафні бали, права та документи", "options": ["Да, при встрече с уполномоченным инструктором по вождению (ADI).", "Да, после прохождения экзамена по вождению.", "Нет, водителя-ученика всегда должен сопровождать квалифицированный водитель.", "Да, во время поездки в экзаменационный центр перед экзаменом по вождению."], "correct": 2, "expl": "Немає винятків — водія-учня завжди повинен супроводжувати кваліфікований водій під час керування автомобілем.", "explSpecific": "Правильно — «Нет, водителя-ученика всегда должен сопровождать квалифицированный водитель». Зустріч з інструктором ADI, складений іспит з водіння чи поїздка до екзаменаційного центру не скасовують обов'язкової вимоги супроводу."}, {"num": 591, "text": "На что может повлиять вождение на недостаточно накачанных шинах?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Система климат-контроля.", "Тормозная способность.", "Выхлопная система.", "Температура двигателя."], "correct": 1, "expl": "Недостатньо накачана шина деформується під навантаженням, зменшуючи ефективну площу контакту з дорогою в потрібний момент гальмування, тому передусім страждає саме гальмівна здатність.", "explSpecific": "Правильно — «Тормозная способность». Клімат-контроль, вихлопна система чи температура двигуна фізично не пов'язані з тиском у шинах."}, {"num": 592, "text": "Какое влияние на автомобиль оказывают недостаточно накачанные шины?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Повышение экономии топлива и торможение.", "Повышение износа двигателя автомобиля.", "Улучшение торможения и рулевого управления.", "Ухудшение торможения и рулевого управления."], "correct": 3, "expl": "Недостатньо накачані шини гірше тримають форму під навантаженням, через що погіршуються і гальмування, і керованість автомобіля.", "explSpecific": "Правильно — «Ухудшение торможения и рулевого управления». Варіанти про покращення економії палива, гальмування чи керування прямо суперечать фізичному ефекту низького тиску; підвищений знос двигуна не є прямим наслідком тиску в шинах."}, {"num": 593, "text": "Может ли человек, прошедший экзамен по вождению в течение последних двух лет, выступать в роли сопровождающего?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Да, если у него есть полноценное водительское удостоверение.", "Да, если он прошел базовую подготовку водителей (EDT).", "Нет, если он не является квалифицированным инструктором по вождению (ADI).", "Нет, он должен являться владельцем полноценного водительского удостоверения в течение не менее 2 лет."], "correct": 3, "expl": "Щоб супроводжувати водія-учня, особа повинна мати повноцінне водійське посвідчення відповідної категорії щонайменше 2 роки — самого факту складання іспиту недавно недостатньо.", "explSpecific": "Правильно — «Нет, он должен являться владельцем полноценного водительского удостоверения в течение не менее 2 лет». Просто наявність посвідчення чи проходження EDT без урахування терміну володіння не відповідають вимозі; статус ADI не є обов'язковою умовою для звичайного супроводжуючого."}, {"num": 594, "text": "Какое влияние оказывает низкое давление в шинах на автомобиль?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Транспортное средство быстрее ускоряется.", "Увеличивается шум двигателя.", "Торможение и движение на поворотах нарушается.", "Перегрев тормозов."], "correct": 2, "expl": "Низький тиск у шинах змінює форму плями контакту з дорогою, через що погіршуються і гальмування, і поведінка автомобіля на поворотах.", "explSpecific": "Правильно — «Торможение и движение на поворотах нарушается». Прискорення руху, шум двигуна чи перегрів гальм не є прямими й типовими наслідками саме низького тиску в шинах."}, {"num": 595, "text": "Когда следует проверять давление в шинах?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Только в установленные интервалы обслуживания.", "Когда шины холодные.", "Когда шины горячие.", "Когда шины частично изношены."], "correct": 1, "expl": "Тиск повітря в шинах потрібно перевіряти, коли шини холодні (до поїздки), оскільки нагрівання під час руху штучно підвищує показник тиску, спотворюючи результат.", "explSpecific": "Правильно — «Когда шины холодные». Прив'язка лише до планових інтервалів обслуговування — надто рідко; перевірка на гарячих чи частково зношених шинах дає неточний або нерелевантний показник."}, {"num": 596, "text": "Во время еженедельной проверки водитель замечает сильно изношенное переднее колесо. Как водителю следует поступить?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Установить изношенную шину на одно из задних колес.", "Заменить изношенную шину.", "Снизить скорость при движении по влажной дороге.", "Проверять давление в шинах, чтобы убедиться, что оно остается постоянным."], "correct": 1, "expl": "Сильно зношена шина небезпечна незалежно від того, на якій осі вона встановлена, тому єдина правильна дія — її заміна, а не переміщення на інше колесо.", "explSpecific": "Правильно — «Заменить изношенную шину». Перестановка зношеної шини на заднє колесо просто переносить небезпеку в інше місце; зниження швидкості чи перевірка тиску не усувають саму причину — критичний знос протектора."}, {"num": 597, "text": "Какое влияние может оказать удар или трение бордюр на шины автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Это приведет к износу протектора.", "Это может увеличить давление воздуха.", "Это приведет к повреждению боковых стенок.", "Это приведет к укреплению боковых стенок."], "correct": 2, "expl": "Сильний удар об бордюр передається саме на бокову стінку шини, яка значно тонша за протектор і найбільш вразлива до прихованих ушкоджень від такого удару.", "explSpecific": "Правильно — «Это приведет к повреждению боковых стенок». Знос протектора спричиняється тертям об дорогу під час руху, а не одноразовим ударом; зміна тиску повітря чи «зміцнення» стінок не є реалістичними наслідками удару об бордюр."}, {"num": 598, "text": "Что подразумевает износ протектора по краю шины?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Некорректное выравнивание рулевого колеса.", "Низкое воздушное давление.", "Автомобиль слишком быстро проезжал повороты.", "Высокое воздушное давление."], "correct": 0, "expl": "Знос протектора саме по краю шини (а не по центру чи рівномірно) — характерна ознака неправильного розвалу/сходження коліс, через що шина торкається дороги нерівномірно.", "explSpecific": "Правильно — «Некорректное выравнивание рулевого колеса». Низький чи високий тиск повітря спричиняє інший характер зносу — по центру або по обох краях одразу; надто швидке проходження поворотів впливає на плечі протектора, а не на один край."}, {"num": 599, "text": "Что касается шин, что должен сделать водитель перед тем как отправиться в длительный путь?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Повысить давление воздуха в шинах.", "Снизить давление воздуха в шинах.", "Уменьшить давление воздуха в передних шинах и увеличить давление воздуха в задних шинах.", "Убедиться, что шины накачаны до нормального воздушного давления."], "correct": 3, "expl": "Перед далекою поїздкою тиск у шинах варто перевірити й довести до нормального значення, вказаного виробником, — без відхилень в жоден бік.", "explSpecific": "Правильно — «Убедиться, что шины накачаны до нормального воздушного давления». Штучне підвищення чи зниження тиску, а тим паче нерівномірний розподіл між осями, погіршують керованість і безпеку замість покращення."}, {"num": 600, "text": "При каких обстоятельствах водитель увеличивает давление воздуха в шинах?", "topic": "Автомагістраль і тунелі", "options": ["Отправляясь в путь с дополнительными пассажирами.", "Когда расстояние пути составляет более 200 км.", "Когда при движении по автомагистрали ожидаются более высокие скорости.", "Когда глубина протектора на шинах ниже 2 мм."], "correct": 0, "expl": "Тиск у шинах варто збільшити (відповідно до рекомендацій виробника), коли автомобіль везе додаткових пасажирів чи вантаж, для компенсації більшого навантаження.", "explSpecific": "Правильно — «Отправляясь в путь с дополнительными пассажирами». Відстань поїздки понад 200 км, очікувана вища швидкість чи знос протектора нижче 2 мм не є стандартними підставами для зміни тиску."}, {"num": 601, "text": "Что должен сделать водитель, чтобы обезопасить автомобиль при замене переднего левого бокового колеса?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Направить передние колеса в сторону бордюра.", "Направить передние колеса от бордюра.", "Убедиться, что автомобиль не покатится при поднятии.", "Убедиться, что рычаг переключения передач находится в нейтральном положении."], "correct": 2, "expl": "Перед підняттям автомобіля домкратом для заміни колеса головна умова безпеки — переконатися, що автомобіль не покотиться, зазвичай задіявши стоянковий гальмо і колісні башмаки.", "explSpecific": "Правильно — «Убедиться, что автомобиль не покатится при поднятии». Напрямок передніх коліс не є головною умовою безпеки саме під час підняття домкратом; нейтральна передача сама по собі не запобігає скочуванню без стоянкового гальма."}, {"num": 602, "text": "Что должен делать водитель, при приближении автомобиля службы скорой помощи с мигающими голубыми огнями?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Ничего не предпринимать и игнорировать автомобиль скорой помощи.", "Внезапно затормозить, чтобы позволить машине скорой помощи проехать", "Реагировать быстро, безопасно и осторожно, чтобы пропустить автомобили скорой помощи.", "Увеличить скорость, чтобы не мешать машине скорой помощи."], "correct": 2, "expl": "Побачивши автомобіль швидкої допомоги з увімкненими проблисковими маячками, водій має швидко, безпечно й обережно звільнити йому шлях, а не ігнорувати ситуацію чи діяти різко.", "explSpecific": "Правильно — «Реагировать быстро, безопасно и осторожно, чтобы пропустить автомобили скорой помощи». Ігнорування ситуації суперечить обов'язку поступитися; різке гальмування чи прискорення, навпаки, підвищують ризик аварії саме в момент, коли екстрений транспорт наближається."}, {"num": 603, "text": "О чем говорит постоянная вибрация рулевого колеса при движении на более высоких скоростях?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Рулевое колесо не выровнено.", "Баланс колес неравномерен.", "Амортизаторы изношены.", "Распределение веса неравномерно."], "correct": 1, "expl": "Постійна вібрація керма саме на високих швидкостях — класична ознака дисбалансу одного чи кількох коліс, які не встигають компенсувати биття при швидкому обертанні.", "explSpecific": "Правильно — «Баланс колес неравномерен». Невирівняне кермо зазвичай проявляється тягою автомобіля вбік, а не вібрацією; зношені амортизатори чи нерівномірний розподіл ваги мають інші, менш специфічні прояви."}, {"num": 604, "text": "Какова наиболее распространенная причина тяжелого рулевого управления?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Плохо смазанное рулевое колесо.", "Недостаточно накачанные шины.", "Слишком накачанные шины.", "Сильно изношенные тормоза."], "correct": 1, "expl": "Недостатньо накачані шини значно збільшують опір коченню й зусилля, потрібне для повороту керма, тому це найпоширеніша причина «важкого» керма.", "explSpecific": "Правильно — «Недостаточно накачанные шины». Погано змащене кермо — рідкісна причина для сучасних авто з гідро- чи електропідсилювачем; перекачані шини чи сильно зношені гальма не є типовою причиною саме важкого керма."}, {"num": 605, "text": "Во время вождения, где водитель должен держать левую ногу?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Под педалью сцепления.", "На педали сцепления.", "На полу или подставке для ног.", "Под педалью тормоза."], "correct": 2, "expl": "Під час звичайного руху ліва нога водія (на авто з механічною коробкою) повинна відпочивати на підлозі чи спеціальній підставці, а не лежати на педалі зчеплення.", "explSpecific": "Правильно — «На полу или подставке для ног». Тримання ноги під чи на педалі зчеплення (навіть без натискання) створює звичку до випадкового часткового натискання, що прискорює знос вижимного підшипника й диска зчеплення."}, {"num": 606, "text": "Каким образом автомобили наносят вред окружающей среде?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Путем повышения уровней радона.", "Путем понижения уровней радона.", "Путем понижения уровней окиси углерода.", "Путем повышения уровней окиси углерода."], "correct": 3, "expl": "Автомобілі шкодять довкіллю насамперед через викиди чадного газу (окису вуглецю) та інших шкідливих речовин з вихлопними газами.", "explSpecific": "Правильно — «Путем повышения уровней окиси углерода». Радон — природний газ, не пов'язаний з викидами автомобілів; «понижение уровней окиси углерода» суперечить реальному ефекту."}, {"num": 607, "text": "Как водитель может помочь окружающей среде?", "topic": "Швидкісний режим", "options": ["Путем снижения скорости.", "Путем резкого торможения.", "Путем повышения скорости.", "Путем резкого ускорения."], "correct": 0, "expl": "Одна з найпростіших дій водія на користь довкілля — рух з поміркованою, а не завищеною швидкістю, що знижує витрату палива та викиди.", "explSpecific": "Правильно — «Путем снижения скорости». Різке гальмування, підвищення швидкості чи різке прискорення — усе це, навпаки, збільшує витрату палива й шкідливі викиди."}, {"num": 608, "text": "Какие альтернативы могут использовать водители для защиты окружающей среды?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Не использовать индикаторы при повороте.", "Использовать только низкие передачи.", "Использовать общественный транспорт.", "Резко ускоряться и тормозить во время вождения."], "correct": 2, "expl": "Одна з найдієвіших альтернатив для зменшення шкоди довкіллю — користуватися громадським транспортом замість особистого автомобіля, коли це можливо.", "explSpecific": "Правильно — «Использовать общественный транспорт». Відмова від поворотників небезпечна для руху й не має екологічного сенсу; їзда лише на низьких передачах чи різкі прискорення й гальмування, навпаки, підвищують витрату палива та шкідливі викиди."}, {"num": 609, "text": "Чего не должен делать водитель, при приближении автомобиля службы скорой помощи с мигающими голубыми огнями?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Очистить путь как можно скорее.", "Внезапно затормозить или заблокировать дорогу.", "Реагировать быстро, безопасно и осторожно, чтобы пропустить автомобили скорой помощи.", "Остановиться на месте, обеспечив достаточно пространства для безопасного движения машины скорой помощи."], "correct": 1, "expl": "При наближенні автомобіля швидкої допомоги водій не повинен різко гальмувати чи блокувати дорогу — це створює додаткову небезпеку саме в момент, коли потрібно швидко звільнити шлях.", "explSpecific": "Правильно — «Внезапно затормозить или заблокировать дорогу» (це саме те, чого НЕ можна робити). Звільнення шляху якнайшвидше, обережне реагування чи зупинка з достатнім простором — усе це правильні, а не заборонені дії у цій ситуації."}, {"num": 610, "text": "Чего можно достигнуть за счет эко-вождения?", "topic": "Дитячі крісла та ремені безпеки", "options": ["Снижение потребления топлива.", "Сокращение времени в пути.", "Увеличение времени в пути.", "Увеличение потребления топлива."], "correct": 0, "expl": "Ремінь безпеки і дитяче крісло працюють за одним принципом — розподілити силу удару по найміцніших частинах тіла і не дати людині вилетіти з салону чи вдаритись об внутрішні поверхні авто. Відповідальність за пристібання дітей молодшого віку лежить на водієві, а не на самій дитині чи батьках, які не за кермом — це і пояснює логіку відповідей у таких питаннях.", "explSpecific": "Правильна відповідь тут — «Снижение потребления топлива». Інші варіанти в цьому питанні («Сокращение времени в пути», «Увеличение времени в пути» та «Увеличение потребления топлива») не відповідають цій вимозі й тому неправильні."}, {"num": 611, "text": "Что способствует эко-вождению?", "topic": "Швидкісний режим", "options": ["Вождение на пониженной передаче на высокой скорости.", "Монтаж багажника на крыше.", "Выбор высокой скорости как можно скорее.", "Резкое торможение."], "correct": 2, "expl": "Економічне водіння передбачає своєчасний перехід на вищі передачі й вихід на комфортну крейсерську швидкість, а не тривалу їзду на низькій передачі з високими обертами.", "explSpecific": "Правильно — «Выбор высокой скорости как можно скорее» (у сенсі — своєчасний вихід на робочу швидкість на відповідній передачі). «Їзда на пониженій передачі на високій швидкості» означає зайве обертання двигуна; багажник на даху погіршує аеродинаміку; різке гальмування витрачає накопичену енергію руху."}, {"num": 612, "text": "Что может сделать водитель, чтобы максимизировать расход топлива во время вождения?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Уменьшить давление во всех шинах.", "Установить багажник на крыше.", "Избегать перевозки ненужного веса.", "Увеличить скорость."], "correct": 2, "expl": "Зайва вага в салоні чи багажнику збільшує витрату палива, тому один із простих способів заощадити — не возити з собою непотрібний вантаж.", "explSpecific": "Правильно — «Избегать перевозки ненужного веса». Зниження тиску в шинах насправді підвищує витрату палива через збільшений опір коченню; багажник на даху погіршує аеродинаміку; збільшення швидкості також підвищує витрату пального."}, {"num": 613, "text": "Какие действия могут привести к увеличению расхода топлива?", "topic": "Швидкісний режим", "options": ["Езда с постоянной скоростью.", "Выключение кондиционера.", "Взгляд вперед и ожидание транспортного потока.", "Резкое ускорение."], "correct": 3, "expl": "Різке прискорення значно підвищує витрату палива, оскільки двигун працює в неефективному режимі високого навантаження.", "explSpecific": "Правильно — «Резкое ускорение». Рух зі сталою швидкістю, вимкнений кондиціонер чи погляд уперед з передбаченням потоку — усе це, навпаки, сприяє економії палива."}, {"num": 614, "text": "Что должен сделать водитель, чтобы свести к минимуму расход топлива в своем автомобиле?", "topic": "Дорожні знаки та розмітка", "options": ["Двигаться осторожно на пониженной передаче.", "Плавно ускоряться и притормаживать.", "Тормозить при приближении к светофору, чтобы быстро остановиться.", "Использовать максимальное ускорение между переключениями передач."], "correct": 1, "expl": "Плавна їзда без різких прискорень і гальмувань — основний спосіб мінімізувати витрату палива, оскільки різкі маневри витрачають значно більше енергії двигуна.", "explSpecific": "Правильно — «Плавно ускоряться и притормаживать». «Обережний рух на пониженій передачі» і «гальмування завчасно для швидкої зупинки» не так ефективні для економії, як плавність; «максимальне прискорення між передачами» — прямо протилежна, найбільш витратна манера їзди."}, {"num": 615, "text": "Как резкое ускорение влияет на расход топлива?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Расход топлива увеличивается.", "Нет никакого эффекта, если включена высокая передача.", "Расход топлива уменьшается.", "Эффект отсутствует, если двигатель настроен правильно."], "correct": 0, "expl": "Різке прискорення вимагає значно більше палива, ніж плавний, поступовий розгін, оскільки двигун працює в неефективному режимі високого навантаження.", "explSpecific": "Правильно — «Расход топлива увеличивается». Твердження про відсутність ефекту на високій передачі чи за правильного налаштування двигуна недооцінюють фізичний вплив різкого прискорення; «зменшується» — прямо протилежний, невірний висновок."}, {"num": 616, "text": "Как непрерывное скоростное вождение влияет на расход топлива?", "topic": "Швидкісний режим", "options": ["Это снижает потребление топлива.", "Это снижает расход топлива, пока дорога прямая.", "Это повышает потребление топлива.", "Расход топлива такой же, как и при более низкой скорости движения."], "correct": 2, "expl": "Постійна їзда на високій швидкості підвищує аеродинамічний опір і витрату палива незалежно від того, пряма дорога чи ні.", "explSpecific": "Правильно — «Это повышает потребление топлива». Твердження про зниження витрати чи «таку саму витрату, як на нижчій швидкості» прямо суперечать фізиці зростання аеродинамічного опору зі швидкістю."}, {"num": 617, "text": "Что должен сделать водитель, чтобы обеспечить лучшую топливную экономичность своего автомобиля?", "topic": "Швидкісний режим", "options": ["Обеспечить постоянное обслуживание автомобиля.", "Обеспечить, чтобы любая нагрузка равномерно распределена на автомобиле.", "Двигаться на более высоких скоростях, чтобы сократить время, затрачиваемое на дорогу.", "Обеспечить, чтобы более тяжелые предметы находились в задней части автомобиля."], "correct": 0, "expl": "Для кращої паливної економічності автомобіль потребує регулярного технічного обслуговування, яке підтримує двигун та інші системи в оптимальному стані.", "explSpecific": "Правильно — «Обеспечить постоянное обслуживание автомобиля». Рівномірний розподіл вантажу важливий, але другорядний фактор; рух на високих швидкостях чи розміщення важких предметів ззаду, навпаки, погіршують паливну економічність."}, {"num": 618, "text": "Как повысить топливную эффективность?", "topic": "Швидкісний режим", "options": ["При использовании анти-парафиновой присадки только в условиях замерзания.", "Путем вождения на пониженной передаче как можно дольше.", "Используя плавное ускорение и переключая передачи согласно скорости.", "Путем ускорения с повышением передачи, чтобы достичь желаемой скорости как можно быстрее."], "correct": 2, "expl": "Підвищити паливну ефективність можна плавним прискоренням і своєчасним перемиканням передач відповідно до швидкості, уникаючи зайвих обертів двигуна.", "explSpecific": "Правильно — «Используя плавное ускорение и переключая передачи согласно скорости». Присадка проти замерзання не має стосунку до паливної ефективності; тривала їзда на пониженій передачі чи прискорення з підвищенням передачі «якнайшвидше» — неекономні звички."}, {"num": 619, "text": "Какое влияние оказывает изношенный выхлоп на автомобиль?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Он приводит к утечке охлаждающей жидкости из двигателя.", "Он вызывает повышение уровня шума и загрязнения газом.", "Снижает потребление топлива.", "Вызывает утечку масла на дорогу."], "correct": 1, "expl": "Зношена вихлопна система (так само, як описано раніше) гірше глушить звук і гірше очищує гази, тому основний ефект — підвищений шум і забруднення довкілля.", "explSpecific": "Правильно — «Он вызывает повышение уровня шума и загрязнения газом». Витік охолоджуючої рідини чи оливи не є типовим наслідком саме зносу вихлопної системи; «знижує споживання палива» не відповідає реальному ефекту зношеного вихлопу."}, {"num": 620, "text": "Когда использование сигнала запрещено?", "topic": "Загальні правила та поведінка на дорозі", "options": ["С 11:30 до 6:00 на любой дороге.", "Всегда в застроенной зоне.", "С 11:30 до 7:00 в застроенной зоне.", "С 10:00 до 6:00 в застроенной зоне."], "correct": 2, "expl": "У нічний час у межах населеного пункту (з 11:30 вечора до 7:00 ранку) використання звукового сигналу заборонено, щоб не турбувати мешканців, окрім екстрених ситуацій.", "explSpecific": "Правильно — «С 11:30 до 7:00 в застроенной зоне». Заборона на будь-якій дорозі чи цілодобова заборона в забудові — надто широкі узагальнення; інший часовий проміжок не відповідає встановленому правилу."}, {"num": 621, "text": "Разрешено ли водителю сигналить во время вождения в застроенном районе ночью?", "topic": "Погодні умови та видимість", "options": ["Да, но с 11:30 до 7:00 сигнал может подаваться только в случае крайней необходимости.", "Да, но только для кратковременного использования.", "Нет, использование сигнала в застроенном районе запрещено с 11:30 до 7:00.", "Да, но только с 11:30 до 7:00."], "correct": 0, "expl": "У забудованому районі вночі (з 11:30 до 7:00) звуковий сигнал дозволений лише в разі крайньої необхідності — наприклад, щоб запобігти аварії, а не для звичного використання.", "explSpecific": "Правильно — «Да, но с 11:30 до 7:00 сигнал может подаваться только в случае крайней необходимости». Повна заборона чи дозвіл лише на «короткочасне використання» не відповідають точному формулюванню правила."}, {"num": 622, "text": "Может ли водитель выключить красный свет или ограничение скорости, чтобы пропустить автомобиль скорой помощи?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Нет, водитель никогда не должен выключать красный свет или ускоряться, чтобы пропустить автомобиль скорой помощи.", "Нет, за исключением случаев, когда перекресток или дорога свободны, тогда водитель может выключить красный свет или ускориться, чтобы пропустить автомобиль скорой помощи.", "Да, водитель может на законных основаниях отключить красный свет, чтобы пропустить автомобиль службы скорой помощи.", "Да, водитель может нарушить ограничение скорости, чтобы пропустить автомобиль скорой помощи."], "correct": 0, "expl": "Навіть щоб пропустити автомобіль екстреної служби, водій не має права порушувати сигнали світлофора чи обмеження швидкості — пропускати потрібно, лише коли це можна зробити, не порушуючи правил.", "explSpecific": "Правильно — «Нет, водитель никогда не должен выключать красный свет или ускоряться». Винятки «якщо перехрестя вільне» чи «на законних підставах» вигадують привілей, якого не існує для звичайних водіїв."}, {"num": 623, "text": "Что может привести к заносу автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Контролируемое ускорение.", "Выбег до остановки.", "Чрезмерное сильное торможение.", "Остановка на четвертой передаче."], "correct": 2, "expl": "Надмірно різке й сильне гальмування може миттєво заблокувати колеса та спричинити втрату зчеплення з дорогою — це один із найпоширеніших сценаріїв заносу.", "explSpecific": "Правильно — «Чрезмерное сильное торможение». Контрольоване прискорення чи виваженого гальмування («выбег до остановки») не спричиняють заносу; зупинка на високій передачі — незручна, але сама по собі не викликає занос."}, {"num": 624, "text": "Что делать водителю, в случае прокола передней шины во время движения?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Немедленно применить ручной тормоз.", "Отпустить руль.", "Крепко схватиться за руль.", "Быстро и резко затормозить."], "correct": 2, "expl": "У разі проколу передньої шини під час руху головне правило — міцно тримати кермо обома руками, щоб автомобіль не потягнуло вбік неконтрольовано, і плавно уповільнюватися.", "explSpecific": "Правильно — «Крепко схватиться за руль». Негайне застосування ручного гальма чи різке гальмування можуть заблокувати колеса й спричинити занос саме в момент втрати керованості; відпускання керма, навпаки, дає автомобілю некеровано з'їхати вбік."}, {"num": 625, "text": "Что делать водителю в случае прокола шины на автомагистрали?", "topic": "Автомагістраль і тунелі", "options": ["Остановиться на полосе движения и включить аварийные огни.", "Остановиться на укрепленной части обочины и вызвать помощь.", "Остановиться на укрепленной части обочины и попросить пассажира предупредить другой транспорт.", "Доехать до ближайшей СТО и обратиться за помощью."], "correct": 1, "expl": "У разі проколу шини на автомагістралі водій повинен зупинитися на укріпленій частині узбіччя і викликати допомогу, а не намагатися замінити колесо на смузі руху.", "explSpecific": "Правильно — «Остановиться на укрепленной части обочины и вызвать помощь». Зупинка на смузі руху вкрай небезпечна; прохання пасажира стояти на дорозі наражає його на смертельну небезпеку."}, {"num": 626, "text": "Какие меры предосторожности может предпринять водитель, чтобы избежать пожара в автомобиле?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Использовать неэтилированный бензин с низким октановым числом.", "Избегать вождения автомобиля с полным баком топлива.", "Иметь подходящий огнетушитель в автомобиле.", "Все заполнять все уровни воды до максимума."], "correct": 2, "expl": "Один з практичних способів запобігти чи оперативно зреагувати на пожежу в автомобілі — тримати в машині відповідний вогнегасник.", "explSpecific": "Правильно — «Иметь подходящий огнетушитель в автомобиле». Марка чи октанове число бензину, рівень палива в баку чи рівень води не є ефективними профілактичними заходами проти займання."}, {"num": 627, "text": "Когда водителю следует использовать аварийные огни?", "topic": "Паркування та зупинка", "options": ["При поломке транспортного средства.", "Когда стоп-сигналы не работают.", "При парковке на короткое время на одной желтой линии.", "При толкании и остановке."], "correct": 0, "expl": "Аварійні вогні насамперед призначені для сигналізації про поломку транспортного засобу, яка створює перешкоду чи небезпеку для інших.", "explSpecific": "Правильно — «При поломке транспортного средства». Несправність стоп-сигналів, коротка стоянка на жовтій лінії чи штовхання автомобіля — не є типовими чи правильними підставами для використання саме аварійних вогнів."}, {"num": 628, "text": "Внезапно затормозить и остановиться, чтобы не создавать препятствий.", "topic": "Паркування та зупинка", "options": ["Включить аварийные огни, выйти из машины и встать в безопасное место.", "Попытаться подать сигнал другому транспорту с задней части автомобиля.", "Выйти из автомобиля и ждать помощи сзади него.", "Остановиться на проезжей части и сообщить другому транспорту о возможности проезда."], "correct": 0, "expl": "Якщо водій різко загальмував і зупинився, щоб не створювати перешкоди, правильна послідовність дій — увімкнути аварійні вогні, вийти з машини і стати в безпечне місце подалі від проїзної частини.", "explSpecific": "Правильно — «Включить аварийные огни, выйти из машины и встать в безопасное место». Спроба сигналізувати іншому транспорту з задньої частини авто чи очікування допомоги позаду машини наражає водія на ризик з боку транспорту, що наближається."}, {"num": 629, "text": "Как водитель должен реагировать на автомобили службы скорой помощи с мигающими синими огнями и/или включенными сиренами?", "topic": "Паркування та зупинка", "options": ["Остановиться у бордюра на обочине, чтобы обеспечить достаточно пространства.", "Посмотреть в зеркала перед тем как отъехать в сторону.", "Отъехать в сторону только если это автомобиль скорой помощи.", "Внезапно затормозить и остановиться, чтобы не создавать препятствий."], "correct": 1, "expl": "Реагуючи на автомобіль швидкої допомоги з увімкненими сигналами, водій повинен спершу подивитися в дзеркала, перш ніж відʼїжджати вбік, щоб не створити нову небезпеку для інших.", "explSpecific": "Правильно — «Посмотреть в зеркала перед тем как отъехать в сторону». Зупинка прямо на узбіччі без перевірки дзеркал чи різке гальмування посеред дороги ризикують створити нову аварію саме в момент маневру."}, {"num": 630, "text": "Что делать водителю, если он видит автомобиль с синими мигающими огнями?", "topic": "Паркування та зупинка", "options": ["Включить аварийные огни автомобиля.", "Моргнуть фарами и съехать на тротуар слева.", "Съехать влево, снизить скорость и, при необходимости, остановиться.", "Моргнуть фарами и немедленно остановиться."], "correct": 2, "expl": "Побачивши автомобіль з синіми проблисковими маячками, водій повинен з'їхати ліворуч, знизити швидкість і за потреби зупинитися, звільняючи шлях.", "explSpecific": "Правильно — «Съехать влево, снизить скорость и, при необходимости, остановиться». Увімкнення власних аварійних вогнів чи виїзд на тротуар — не є правильною реакцією; миготіння фарами із негайною зупинкою посеред дороги так само небезпечне."}, {"num": 631, "text": "Что должен делать водитель, когда видит дорожную технику с желтыми проблесковыми огнями впереди?", "topic": "Швидкісний режим", "options": ["Развернуться, поскольку дорога впереди заблокирована.", "Замедлиться и включить 1-ую передачу.", "Продолжать движение с той же скоростью.", "Снизить скорость и быть готовым остановиться, при необходимости."], "correct": 3, "expl": "Побачивши попереду дорожню техніку з жовтими проблисковими вогнями, водій повинен знизити швидкість і бути готовим зупинитися.", "explSpecific": "Правильно — «Снизить скорость и быть готовым остановиться, при необходимости». Розворот через «заблоковану дорогу» — передчасний висновок; збереження швидкості чи ввімкнення першої передачі без зниження швидкості недостатньо обережні."}, {"num": 632, "text": "Что должен делать водитель, если впереди остановился автомобиль скорой помощи с мигающими голубыми огнями?", "topic": "Обгін та зміна смуги руху", "options": ["Немедленно остановиться, чтобы посмотреть, что случилось.", "Двигаться к центру дороги, чтобы препятствовать обгону другими транспортными средствами.", "Остановиться и предложить помощь.", "Снизить скорость и быть готовым остановиться, при необходимости."], "correct": 3, "expl": "Побачивши попереду зупинений автомобіль швидкої допомоги з увімкненими маячками, водій повинен знизити швидкість і бути готовим зупинитися, оскільки ситуація попереду невідома.", "explSpecific": "Правильно — «Снизить скорость и быть готовым остановиться, при необходимости». Негайна зупинка чи пропозиція допомоги без потреби створюють зайву перешкоду; виїзд до центру дороги — небезпечна дія."}, {"num": 633, "text": "Как различить аварийно-спасательные транспортные средства?", "topic": "Технічні несправності та аварійні ситуації", "options": ["По мигающим желтым и белым огням.", "По постоянно горящим красным огням.", "По мигающим красным и или синим огням.", "По мигающим зеленым огням."], "correct": 2, "expl": "Аварійно-рятувальні транспортні засоби (швидка, поліція, пожежна) розпізнають насамперед за проблисковими маячками — синіми та/або червоними, залежно від служби і юрисдикції.", "explSpecific": "Правильно — «По мигающим красным и или синим огням». Жовті й білі, лише постійно горящі червоні чи мигаючі зелені вогні не є стандартним розпізнавальним сигналом екстрених служб."}, {"num": 634, "text": "Какое транспортное средство освобождается от ограничений скорости при использовании в чрезвычайной ситуации?", "topic": "Швидкісний режим", "options": ["Пожарная бригада.", "Горная спасательная служба.", "Доктор по вызову.", "Служба аварийного восстановления."], "correct": 0, "expl": "Від обмежень швидкості в надзвичайній ситуації звільняються екстрені служби, зокрема пожежна бригада, під час виконання термінового виїзду.", "explSpecific": "Правильно — «Пожарная бригада». Гірська рятувальна служба, виклик лікаря чи служба аварійного відновлення не входять до стандартного переліку служб, звільнених від обмежень швидкості, у цьому варіанті питання."}, {"num": 635, "text": "Согласно Отчету о ДТП, какой пол более склонен к вождению в нетрезвом виде, которое влекло за собой столкновение со смертельным исходом?", "topic": "Статистика ДТП", "options": ["Количество мужчины и женщин, садящихся за руль в нетрезвом виде, одинаково.", "Женщины.", "Ни мужчины, ни женщины не садятся за руль в нетрезвом виде.", "Мужчины."], "correct": 3, "expl": "Ці питання ґрунтуються на реальних офіційних звітах про дорожньо-транспортні пригоди в Ірландії (наприклад, дані про вплив алкоголю, стать водіїв, поведінку свідків на місці ДТП). Тут немає логічного виведення відповіді — це конкретні факти зі звітів, які потрібно просто запам'ятати.", "explSpecific": "Правильна відповідь тут — «Мужчины». Інші варіанти в цьому питанні («Количество мужчины и женщин, садящихся за руль в нетрезвом виде, одинаково», «Женщины» та «Ни мужчины, ни женщины не садятся за руль в нетрезвом виде») не відповідають цій вимозі й тому неправильні."}, {"num": 636, "text": "Согласно Отчету о ДТП, по вине нетрезвых водителей каких транспортных средств происходило большинство столкновений со смертельным исходом?", "topic": "Статистика ДТП", "options": ["Мотоцикл.", "Трактор", "Грузовик", "Личный автомобиль"], "correct": 3, "expl": "Це вразливі учасники руху — при зіткненні саме вони найбільше постраждають, тому правила завжди вимагають від водія автомобіля брати на себе більше відповідальності: пропускати, давати більшу дистанцію при обгоні, бути особливо уважним на переходах і перехрестях, де пішохід чи велосипедист може бути непомітний (сліпі зони, дзеркала). Правильна відповідь у цій темі майже завжди та, що надає їм пріоритет або збільшує дистанцію до них.", "explSpecific": "Правильна відповідь тут — «Личный автомобиль». Інші варіанти в цьому питанні («Мотоцикл», «Трактор» та «Грузовик») не відповідають цій вимозі й тому неправильні."}, {"num": 637, "text": "Согласно Отчету о ДТП, к какому типу столкновений со смертельным исходом человек мог быть причастен при вождении в нетрезвом виде?", "topic": "Статистика ДТП", "options": ["Столкновение с участием одного автомобиля.", "Столкновение с пешеходом.", "Столкновение с мотоциклистом.", "Столкновение с участием нескольких автомобилей."], "correct": 0, "expl": "Це вразливі учасники руху — при зіткненні саме вони найбільше постраждають, тому правила завжди вимагають від водія автомобіля брати на себе більше відповідальності: пропускати, давати більшу дистанцію при обгоні, бути особливо уважним на переходах і перехрестях, де пішохід чи велосипедист може бути непомітний (сліпі зони, дзеркала). Правильна відповідь у цій темі майже завжди та, що надає їм пріоритет або збільшує дистанцію до них.", "explSpecific": "Правильна відповідь тут — «Столкновение с участием одного автомобиля». Інші варіанти в цьому питанні («Столкновение с пешеходом», «Столкновение с мотоциклистом» та «Столкновение с участием нескольких автомобилей») не відповідають цій вимозі й тому неправильні."}, {"num": 638, "text": "Согласно Отчету о ДТП, в какие дни недели существовала большая вероятность вождения в нетрезвом виде, которое влекло за собой столкновение со смертельным исходом?", "topic": "Статистика ДТП", "options": ["Четверг и Пятница", "Воскресенье и понедельник", "Суббота и воскресенье", "Пятница и суббота"], "correct": 2, "expl": "Ці питання ґрунтуються на реальних офіційних звітах про дорожньо-транспортні пригоди в Ірландії (наприклад, дані про вплив алкоголю, стать водіїв, поведінку свідків на місці ДТП). Тут немає логічного виведення відповіді — це конкретні факти зі звітів, які потрібно просто запам'ятати.", "explSpecific": "Правильна відповідь тут — «Суббота и воскресенье». Інші варіанти в цьому питанні («Четверг и Пятница», «Воскресенье и понедельник» та «Пятница и суббота») не відповідають цій вимозі й тому неправильні."}, {"num": 639, "text": "Согласно отчету о ДТП, как употребление алкоголя влияет на решение человека использовать ремень безопасности?", "topic": "Алкоголь, наркотики, втома водія", "options": ["Водители и пассажиры реже пристегивались ремнями безопасности.", "Водители и пассажиры чаще пристегивались ремнями безопасности.", "Никак не влияет.", "В зависимости от выпитого алкоголя."], "correct": 0, "expl": "Згідно зі звітом про ДТП, вживання алкоголю пов'язане зі зниженням дисципліни використання ременів безпеки — водії й пасажири під впливом алкоголю рідше пристібалися.", "explSpecific": "Правильно — «Водители и пассажиры реже пристегивались ремнями безопасности». Твердження про частіше пристібання, відсутність впливу чи залежність від кількості випитого не відповідають наведеній статистиці."}, {"num": 640, "text": "Каков минимальный уровень концентрации алкоголя в крови (ВАС), при котором ученик или начинающий водитель совершает преступление?", "topic": "Алкоголь, наркотики, втома водія", "options": ["20 мг.", "30 мг.", "40 мг.", "10 мг."], "correct": 0, "expl": "Для водія-учня чи водія-початківця мінімальний рівень концентрації алкоголю в крові (BAC), за якого настає порушення, становить лише 20 мг — значно нижче, ніж для досвідчених водіїв.", "explSpecific": "Правильно — «20 мг». Значення 10, 30 чи 40 мг не відповідають встановленому законом суворому порогу саме для учнів і початківців."}, {"num": 641, "text": "Каков максимальный срок дисквалификации, установленный в суде, если у ученика-водителя уровень концентрации алкоголя в крови (BAC) превышает 80 мг?", "topic": "Алкоголь, наркотики, втома водія", "options": ["6 лет.", "2 года.", "4 года.", "1 год."], "correct": 0, "expl": "Максимальний термін дискваліфікації, який суд може встановити для водія-учня з рівнем алкоголю в крові понад 80 мг, становить 6 років.", "explSpecific": "Правильно — «6 лет». 1, 2 чи 4 роки — менші терміни, що не відповідають максимально можливому покаранню в суді."}, {"num": 642, "text": "Согласно статистике, в какой возрастной группе было наибольшее количество погибших пассажиров в столкновениях, в которых алкоголь был основным фактором?", "topic": "Алкоголь, наркотики, втома водія", "options": ["25-34 года.", "10-16 лет.", "17-24 года.", "50-65 лет."], "correct": 2, "expl": "Згідно зі статистикою, найбільша кількість загиблих пасажирів у зіткненнях, де алкоголь був основним фактором, припадає на вікову групу 17–24 роки.", "explSpecific": "Правильно — «17-24 года». Групи 25–34, 10–16 чи 50–65 років не відповідають наведеній у статистиці найбільш ураженій віковій категорії."}, {"num": 643, "text": "Согласно статистике, сколько людей были убиты водителями, употреблявшими спиртные напитки прежде чем сесть за руль.", "topic": "Загальні правила та поведінка на дорозі", "options": ["Более 251", "Более 5", "Менее 251", "Более 100"], "correct": 0, "expl": "Згідно зі статистикою ДТП, кількість людей, загиблих з вини нетверезих водіїв, вимірюється сотнями — офіційна цифра перевищує 251.", "explSpecific": "Правильно — «Более 251», згідно з офіційною статистикою. Менші чи явно занижені числа не відповідають зафіксованому офіційному показнику."}, {"num": 644, "text": "Водителя автоматически лишают водительских прав управлять автомобилем до тех пор, пока он не предоставит сотруднику Гарды образец крови, мочи или выдыхаемого воздуха?", "topic": "Штрафні бали, права та документи", "options": ["2 года.", "4 года.", "3 года.", "1 год."], "correct": 1, "expl": "Водія автоматично позбавляють права керувати автомобілем на 4 роки, якщо він не надає співробітнику Гарди зразок крові, сечі чи видихуваного повітря.", "explSpecific": "Правильно — «4 года». 1, 2 чи 3 роки не відповідають встановленому терміну автоматичної дискваліфікації за відмову від надання зразка."}, {"num": 645, "text": "Что из нижеперечисленного является возможным последствием для водителя-ученика, если он сядет за руль, выпив всего одну единицу алкоголя?", "topic": "Алкоголь, наркотики, втома водія", "options": ["Лишение прав на три месяца.", "Лишение прав на один месяц.", "Штраф в размере 60 евро.", "Штраф в размере 90 евро."], "correct": 0, "expl": "Якщо водій-учень сяде за кермо, випивши навіть лише одну одиницю алкоголю, можливим наслідком є позбавлення прав на три місяці.", "explSpecific": "Правильно — «Лишение прав на три месяца». Один місяць позбавлення прав чи штрафи 60 або 90 євро не відповідають встановленому покаранню за це порушення для учня."}, {"num": 646, "text": "Согласно Отчету о ДТП, причиной скольких столкновений со смертельным исходом из 867 послужило алкогольное опьянение?", "topic": "Алкоголь, наркотики, втома водія", "options": ["201-250", "251-350", "Менее 100", "101-200"], "correct": 1, "expl": "Згідно зі звітом про ДТП, з 867 зіткнень зі смертельним наслідком причиною алкогольного сп'яніння стали від 251 до 350 випадків.", "explSpecific": "Правильно — «251-350». Діапазони 201–250, менше 100 чи 101–200 не відповідають наведеній у звіті статистиці."}, {"num": 647, "text": "Согласно статистике, в какой возрастной группе было наибольшее количество погибших пассажиров в столкновениях, в которых алкоголь был основным фактором?", "topic": "Алкоголь, наркотики, втома водія", "options": ["25-34 лет.", "10-16 лет.", "17-24 лет.", "50-65 лет."], "correct": 2, "expl": "Той самий статистичний факт — найбільша кількість загиблих пасажирів у зіткненнях, де алкоголь був основним фактором, припадає на вікову групу 17–24 роки.", "explSpecific": "Правильно — «17-24 лет». Групи 25–34, 10–16 чи 50–65 років не відповідають наведеній статистиці."}, {"num": 648, "text": "Согласно предварительному отчету о ДТП, сколько пассажиров погибло в столкновении, где алкоголь был известным фактором?", "topic": "Алкоголь, наркотики, втома водія", "options": ["Более 91.", "От 71 до 90.", "Менее 35.", "От 36 до 70."], "correct": 1, "expl": "Згідно з попереднім звітом про ДТП, у зіткненнях, де алкоголь був відомим фактором, загинуло від 71 до 90 пасажирів.", "explSpecific": "Правильно — «От 71 до 90». Показники «более 91», «менее 35» чи «от 36 до 70» не відповідають наведеній у звіті статистиці."}, {"num": 649, "text": "Согласно предварительному отчету о ДТП, какой процент из 169 водителей, погибших в результате столкновения, употребляли алкоголь?", "topic": "Алкоголь, наркотики, втома водія", "options": ["72%", "62%", "52%", "92%"], "correct": 3, "expl": "Згідно з попереднім звітом про ДТП, серед 169 загиблих водіїв 92% вживали алкоголь.", "explSpecific": "Правильно — «92%». Показники 72%, 62% чи 52% занижують реальну частку, наведену в звіті."}, {"num": 650, "text": "Согласно предварительному отчету о ДТП, сколько пешеходов погибло по причине употребления ими алкоголя?", "topic": "Алкоголь, наркотики, втома водія", "options": ["Менее 10.", "От 20 до 40.", "От 41 до 90.", "Более 100."], "correct": 2, "expl": "Згідно з попереднім звітом про ДТП, від вживання алкоголю загинуло від 41 до 90 пішоходів.", "explSpecific": "Правильно — «От 41 до 90». Показники «менее 10», «от 20 до 40» чи «более 100» не відповідають наведеній у звіті статистиці."}, {"num": 651, "text": "Согласно Отчету о ДТП, причиной скольких столкновений со смертельным исходом послужило алкогольное опьянение?", "topic": "Алкоголь, наркотики, втома водія", "options": ["4 из 10", "3 из 5", "10 из 10", "100 из 200"], "correct": 0, "expl": "Згідно зі звітом про ДТП, причиною близько 4 з кожних 10 смертельних зіткнень є алкогольне сп'яніння.", "explSpecific": "Правильно — «4 из 10». Значення «3 из 5», «10 из 10» чи «100 из 200» не відповідають наведеному у звіті співвідношенню."}, {"num": 652, "text": "Что означает эта дорожная разметка?", "topic": "Дорожні знаки та розмітка", "options": ["Водители должны держаться слева от сплошной белой линии.", "Встречный транспортный поток может пересечь линию для обгона.", "Водители могут пересечь линию для обгона.", "Только мотоциклисты могут пересечь линии для обгона."], "correct": 0, "expl": "Той самий тип суцільної білої лінії розмітки, що завжди означає обов'язок водіїв залишатися зі свого боку.", "explSpecific": "Правильно — «Водители должны держаться слева от сплошной белой линии», з тих самих причин: суцільна лінія забороняє перетин для всіх категорій транспорту без винятків.", "img": "q652.png"}, {"num": 653, "text": "Что означает мигающая желтая стрелка, указывающая налево на светофоре?", "topic": "Дорожні знаки та розмітка", "options": ["Водитель может повернуть налево, но уступить дорогу транспорту на другой дороге.", "Водитель не должен двигаться в этом направлении.", "Водитель может продолжить движение перед транспортом на другой дороге.", "Водитель должен подождать, пока не загорится зеленый свет светофора."], "correct": 0, "expl": "Той самий сигнал мигаючої жовтої стрілки ліворуч — дозволяє рух за умови поступливості.", "explSpecific": "Правильно — «Водитель может повернуть налево, но уступить дорогу транспорту на другой дороге», з тих самих причин: мигання завжди означає дозвіл із умовою поступливості, а не безумовний наказ чи заборону.", "img": "q653.png"}, {"num": 654, "text": "Каков максимальный предел скорости автомобилей и мотоциклов на автострадах?", "topic": "Швидкісний режим", "options": ["60 км/ч.", "80 км/ч.", "100 км/ ч.", "120 км/ч."], "correct": 2, "expl": "На автострадах (не автомагістралях) стандартна максимальна швидкість для легкових автомобілів і мотоциклів становить 100 км/год.", "explSpecific": "Правильно — «100 км/ч». Автострада має нижчу межу, ніж автомагістраль (120 км/ч); 60 і 80 км/ч не відповідають стандартному обмеженню саме для автостради."}, {"num": 655, "text": "Когда разрешается стоянка на тротуаре?", "topic": "Паркування та зупинка", "options": ["Когда на пешеходной дорожке находится не более половины транспортного средства.", "Когда транспортные средства припаркованы с обеих сторон дороги.", "Стоянка на пешеходной дорожке запрещена.", "Когда хотя бы половина пешеходной дорожки остается свободной для пешеходов."], "correct": 2, "expl": "Стоянка на тротуарі (пішохідній доріжці) в Ірландії заборонена повністю, незалежно від того, скільки місця залишається вільним для пішоходів.", "explSpecific": "Правильно — «Стоянка на пешеходной дорожке запрещена» без винятків. Варіанти про «не більше половини ТЗ» чи «половина доріжки вільна» вигадують часткові дозволи, яких правило не передбачає."}, {"num": 656, "text": "При движении по дороге с трамвайными линиями, почему водитель должен проявлять особую осторожность?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Езда по рельсам может улучшить торможение.", "Езда по рельсам может уменьшить сцепление шин.", "Езда по рельсам может увеличить сцепление шин.", "Езда по рельсам может улучшить рулевое управление."], "correct": 1, "expl": "Металева поверхня трамвайних рейок значно слизькіша за асфальт, особливо у вологу погоду, тому проїзд по них знижує зчеплення шин з дорогою.", "explSpecific": "Правильно — «Езда по рельсам может уменьшить сцепление шин». Твердження про покращення гальмування, зчеплення чи керування прямо суперечать фізичним властивостям слизького металу рейок.", "img": "q656.png"}, {"num": 657, "text": "Что должен делать водитель, если он едет по полосе движения и не собирается обгонять?", "topic": "Обгін та зміна смуги руху", "options": ["Держаться подальше и оставить пространство для обгона другим водителям.", "Включить левый поворот, чтобы подать сигнал другому транспорту о возможности обгона.", "Держаться ближе к транспортному средству, едущему впереди.", "Подать сигнал следующему транспорту о возможности обгона."], "correct": 0, "expl": "Якщо водій рухається смугою і сам не збирається обганяти, варто триматися на більшій дистанції від транспорту попереду, залишаючи простір для обгону іншим учасникам руху.", "explSpecific": "Правильно — «Держаться подальше и оставить пространство для обгона другим водителям». Увімкнення лівого поворотника без наміру повернути чи наближення впритул — неправильні дії."}, {"num": 658, "text": "В сырую погоду, как водитель может оценить безопасное расстояние от автомобиля, следующего впереди?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Время прохождения расстояния от фиксированной точки, проходимой вашим автомобилем до автомобиля, следующего впереди, должно оставлять не менее 2 секунд.", "Обеспечив расстояние, равное двум длинам транспортного средства между автомобилями.", "Обеспечив время прохождения расстояния от фиксированной точки, проходимой вашим автомобилем до автомобиля, следующего впереди, равное не менее 4 секунд.", "Обеспечив расстояние, равное четырем длинам транспортного средства между автомобилями."], "correct": 2, "expl": "У вологу погоду безпечна дистанція оцінюється часовим методом — не менш ніж 4 секунди проходження фіксованої точки, а не фіксованою кількістю довжин автомобіля.", "explSpecific": "Правильно — «не менее 4 секунд». Вимірювання довжинами автомобіля — менш точний і не рекомендований офіційно метод; «2 секунди» — норма для сухої, а не вологої дороги."}, {"num": 659, "text": "Что это может означать быстрый щелкающий звук при нажатии на индикаторный выключатель?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Регулятор напряжения работает некорректно.", "Возможно, перегорела лампочка индикатора.", "Неисправен выключатель аварийной сигнализации.", "Предупреждающие огни включены."], "correct": 1, "expl": "Швидке клацання поворотника — та сама класична ознака перегорілої лампочки покажчика повороту, що й у попередньому питанні на цю тему.", "explSpecific": "Правильно — «Возможно, перегорела лампочка индикатора». Несправність регулятора напруги, вимикача аварійної сигналізації чи включені попереджувальні вогні не пов'язані саме зі зміною частоти клацання."}, {"num": 660, "text": "Что делать, если щетки стеклоочистителя не очищают ветровое стекло?", "topic": "Швидкісний режим", "options": ["Долить жидкость в бак стеклоомывателя.", "Проверить работу аккумулятора.", "Переключить щетки на максимальную скорость.", "Переключить щетки на минимальную скорость."], "correct": 2, "expl": "Якщо щітки склоочисника погано очищують лобове скло, спершу варто спробувати перемкнути їх на максимальну швидкість роботи.", "explSpecific": "Правильно — «Переключить щетки на максимальную скорость». Доливання рідини омивача чи перевірка акумулятора не вирішують проблему неефективного очищення саме щітками; перемикання на мінімальну швидкість, навпаки, ще менше очищує скло."}, {"num": 661, "text": "Что водитель должен регулярно проверять, чтобы обеспечить себе хороший четкий обзор дороги во время вождения?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Убедиться, что в баке достаточно топлива.", "Следить за прогнозом погоды.", "В бачке омывателя ветрового стекла достаточно жидкости.", "Проверить качество тормозной жидкости."], "correct": 2, "expl": "Для чіткого огляду дороги під час дощу чи бруду водієві потрібна омивальна рідина для скла — тому її рівень варто регулярно перевіряти.", "explSpecific": "Правильно — «В бачке омывателя ветрового стекла достаточно жидкости». Рівень палива, прогноз погоди чи якість гальмівної рідини не пов'язані безпосередньо із чіткістю огляду через лобове скло."}, {"num": 662, "text": "Что водитель должен регулярно проверять, чтобы обеспечить себе хороший четкий обзор дороги во время вождения?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Следить за прогнозом погоды.", "Проверить правильность работы климат-контроля.", "Правильность работы щеток стеклоочистителя.", "Правильность работы топливного насоса."], "correct": 2, "expl": "Для чіткого огляду дороги під час дощу критично важлива справна робота щіток склоочисника — без них лобове скло швидко втрачає прозорість.", "explSpecific": "Правильно — «Правильность работы щеток стеклоочистителя». Прогноз погоди, клімат-контроль чи паливний насос не мають прямого стосунку до чіткості огляду через лобове скло."}, {"num": 663, "text": "Каким транспортным средствам разрешается ехать по велосипедной дорожке с прерывистой белой линией?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Велосипедистам и пользователям механических инвалидных колясок.", "Велосипедистам и мотоциклистам.", "Автобусам и велосипедистам.", "Велосипедистам и такси."], "correct": 0, "expl": "Велосипедна доріжка з переривчастою білою лінією менш строго відокремлена від дороги, але дозволені користувачі ті самі — велосипедисти й користувачі механічних інвалідних візків.", "explSpecific": "Правильно — «Велосипедистам и пользователям механических инвалидных колясок». Мотоцикли, автобуси й таксі не входять до переліку дозволених користувачів велосипедної доріжки незалежно від типу розмітки."}, {"num": 664, "text": "Приближающийся водитель заметил, что мальчик на детском велосипеде попрощался со своим другом. Как следует поступить водителю в этой ситуации?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Быть готовым к тому, что мальчик тронется в любой момент.", "Замедлиться и подать мальчику сигнал о пересечении дороги.", "Продолжить движение, пока мальчик находится на тротуаре.", "Остановиться и дождаться, пока мальчик не тронется."], "correct": 0, "expl": "Побачивши дитину на велосипеді біля дороги, яка щойно попрощалася з другом, водій повинен бути готовим, що вона рушить у будь-яку мить, оскільки поведінка дітей непередбачувана.", "explSpecific": "Правильно — «Быть готовым к тому, что мальчик тронется в любой момент». Подача сигналу про перехід чи очікування, поки хлопчик рушить, — пасивні реакції; продовження руху «поки хлопчик на тротуарі» недооцінює швидкість дитини.", "img": "q664.png"}, {"num": 665, "text": "Что значит сплошная белая линия в центре дороги?", "topic": "Обгін та зміна смуги руху", "options": ["Разворот разрешен в светлое время суток.", "Транспорт может совершить обгон.", "Разворот запрещен.", "Стоянка разрешена в рабочие часы."], "correct": 2, "expl": "Суцільна біла лінія по центру дороги забороняє її перетин у будь-якому напрямку — а отже, забороняє й розворот, який неминуче потребує перетину такої лінії.", "explSpecific": "Правильно — «Разворот запрещен». «Транспорт може обганяти» і «стоянка дозволена в робочі години» суперечать самій суті суцільної забороняючої лінії; «розворот дозволено вдень» вигадує виняток, якого немає.", "img": "q665.png"}, {"num": 666, "text": "Что значит белая линия в центре дороги?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Транспортные средства не могут пересекать эту линию.", "Транспортные средства могут пересекать эту линию.", "Вблизи находится пешеходный переход.", "Вблизи нет пешеходных пешеходов."], "correct": 0, "expl": "Суцільна біла лінія по центру дороги забороняє транспорту перетинати чи виїжджати на неї — базове правило суцільної розмітки.", "explSpecific": "Правильно — «Транспортные средства не могут пересекать эту линию». Дозвіл перетину прямо суперечить суті суцільної лінії; згадки про пішохідний перехід — вигадане, не пов'язане з характером самої лінії тлумачення.", "img": "q666.png"}, {"num": 667, "text": "Что следует делать водителю увидев желтый свет светофора?", "topic": "Дорожні знаки та розмітка", "options": ["Продолжить движение, поскольку на перекрестке нет другого транспорта.", "Продолжить движение только убедившись в отсутствии пешеходов.", "Остаться на линии, если это безопасно.", "Проехать на этот свет до того, как загорится красный."], "correct": 2, "expl": "Побачивши жовтий сигнал світлофора, водій має зупинитися, якщо це безпечно, і лише за неможливості безпечної зупинки — залишитися на лінії й завершити проїзд перехрестя.", "explSpecific": "Правильно — «Остаться на линии, если это безопасно». «Продовжити рух, бо немає іншого транспорту чи пішоходів» і «проїхати до того, як загориться червоний» описують необережне ігнорування сигналу, а не обґрунтоване рішення щодо безпеки зупинки.", "img": "q667.png"}, {"num": 668, "text": "Каков минимальный рекомендуемый тормозной путь для автомобиля, движущегося со скоростью 50 км / ч по сухой дороге", "topic": "Технічні несправності та аварійні ситуації", "options": ["55 метров.", "25 метров.", "15 метров.", "5 метров."], "correct": 1, "expl": "Той самий показник мінімального гальмівного шляху на сухій дорозі при 50 км/год, що вже наводився раніше в цій темі.", "explSpecific": "Правильно — «25 метров», згідно з офіційною таблицею гальмівних шляхів для сухої дороги на 50 км/год."}, {"num": 669, "text": "Каков минимальный рекомендуемый тормозной путь для автомобиля, движущегося со скоростью 50 км / ч по влажной дороге?", "topic": "Технічні несправності та аварійні ситуації", "options": ["56 метров.", "36 метров.", "76 метров.", "16 метров."], "correct": 1, "expl": "Той самий показник мінімального гальмівного шляху на вологій дорозі при 50 км/год.", "explSpecific": "Правильно — «36 метров», згідно з офіційною таблицею гальмівних шляхів для вологої дороги на 50 км/год."}, {"num": 670, "text": "Каков минимальный рекомендуемый тормозной путь для автомобиля, движущегося со скоростью 100 км / ч по сухой дороге?", "topic": "Технічні несправності та аварійні ситуації", "options": ["70 метров.", "120 метров.", "90 метров.", "30 метров."], "correct": 0, "expl": "Той самий показник мінімального гальмівного шляху на сухій дорозі при 100 км/год.", "explSpecific": "Правильно — «70 метров», згідно з офіційною таблицею гальмівних шляхів для сухої дороги на 100 км/год."}, {"num": 671, "text": "Каков минимальный рекомендуемый тормозной путь для автомобиля, движущегося со скоростью 100 км / ч по влажной дороге?", "topic": "Технічні несправності та аварійні ситуації", "options": ["121 метров.", "61 метр.", "81 метр.", "111метров."], "correct": 0, "expl": "На вологій дорозі при швидкості 100 км/год гальмівний шлях зростає найбільше з усіх наведених комбінацій швидкості й покриття через поєднання високої кінетичної енергії й низького зчеплення.", "explSpecific": "Правильно — «121 метров», згідно з офіційною таблицею гальмівних шляхів для вологої дороги на 100 км/год. Інші числа не відповідають встановленому офіційному значенню."}, {"num": 672, "text": "Что должен делать водитель при движении ночью будучи ослепленным светом фар встречного автомобиля?", "topic": "Погодні умови та видимість", "options": ["Несколько раз моргните фарами, чтобы предупредить нарушающего водителя.", "Посмотреть в сторону и замедлить движение и остановиться, при необходимости.", "Снизить скорость и включить фары дальнего света.", "Переместиться влево и продолжать движение с нормальной скоростью."], "correct": 1, "expl": "Осліплений вночі фарами зустрічного авто водій повинен відвести погляд убік від джерела світла, знизити швидкість і за потреби зупинитися.", "explSpecific": "Правильно — «Посмотреть в сторону и замедлить движение и остановиться, при необходимости». Миготіння фарами у відповідь не вирішує проблему власної засліпленості."}, {"num": 673, "text": "Какое утверждение верно в отношении давления в шинах и движения по автомагистрали?", "topic": "Автомагістраль і тунелі", "options": ["Водитель должен увеличить давление в задних шинах, чтобы справиться с устойчивой высокой скоростью.", "Водитель должен увеличить давление в передних шинах, чтобы справиться с устойчивой высокой скоростью.", "Водитель должен уменьшить давление в шинах, поскольку высокие скорости вызовут их нагрев.", "Водитель должен убедиться, что давление в шинах нормальное."], "correct": 3, "expl": "Той самий принцип — перед рухом автомагістраллю тиск у шинах має відповідати нормальному (рекомендованому виробником) значенню, а не штучно змінюватися через швидкість.", "explSpecific": "Правильно — «Водитель должен убедиться, что давление в шинах нормальное». Збільшення тиску лише в задніх чи передніх шинах або його зменшення через нагрів — необґрунтовані й небезпечні дії."}, {"num": 674, "text": "Как водитель-ученик может реагировать в необычных дорожных ситуациях?", "topic": "Штрафні бали, права та документи", "options": ["Медленнее, чем опытный водитель.", "Быстрее, чем опытный водитель.", "Так-же как и опытный водитель.", "Лучше, чем опытный водитель."], "correct": 0, "expl": "Водій-учень має менше досвіду розпізнавання і реагування на нестандартні дорожні ситуації, тому реагує повільніше, ніж досвідчений водій.", "explSpecific": "Правильно — «Медленнее, чем опытный водитель». Твердження про однакову, швидшу чи кращу реакцію не відповідають реальному рівню досвіду учня."}, {"num": 675, "text": "Что должен делать водитель, если видит слева бегунов?", "topic": "Обгін та зміна смуги руху", "options": ["Посмотреть в зеркала, включить поворот и совершить обгон, предоставив им достаточно пространства.", "Подождать, пока они не уйдут с пути водителя.", "Включить поворот и обогнать, предоставив им достаточно пространства.", "Подать звуковой сигнал и включить фары, чтобы предупредить их о своем присутствии."], "correct": 0, "expl": "Обганяючи бігунів на дорозі, водій має дотримуватися стандартної послідовності безпечного обгону: дзеркала, сигнал, а потім сам маневр з достатньою бічною дистанцією.", "explSpecific": "Правильно — «Посмотреть в зеркала, включить поворот и совершить обгон, предоставив им достаточно пространства». Очікування, поки бігуни самі зійдуть з дороги, — пасивна стратегія; звуковий сигнал і фари можуть налякати бігунів."}, {"num": 676, "text": "Что нужно знать водителю при повороте налево?", "topic": "Обгін та зміна смуги руху", "options": ["У следующего за вами транспорта должно быть достаточно пространства для обгона.", "Велосипедисты могут появиться слева.", "Подъехать как можно ближе к бордюру.", "Велосипедисты могут появиться справа."], "correct": 1, "expl": "Повертаючи ліворуч, водій повинен пам'ятати, що велосипедист може одночасно рухатися прямо вздовж його лівого боку, залишаючись непоміченим у сліпій зоні.", "explSpecific": "Правильно — «Велосипедисты могут появиться слева». Достатність простору для обгону транспорту позаду не є головною небезпекою саме при повороті ліворуч; поява велосипедиста справа менш імовірна тут."}, {"num": 677, "text": "К чему ведет неправильная регулировка фар?", "topic": "Дитячі крісла та ремені безпеки", "options": ["Это может привести к сокращению срока службы батареи.", "К ослеплению встречных водителей.", "К возгоранию.", "К преждевременному износу ламп."], "correct": 1, "expl": "Ремінь безпеки і дитяче крісло працюють за одним принципом — розподілити силу удару по найміцніших частинах тіла і не дати людині вилетіти з салону чи вдаритись об внутрішні поверхні авто. Відповідальність за пристібання дітей молодшого віку лежить на водієві, а не на самій дитині чи батьках, які не за кермом — це і пояснює логіку відповідей у таких питаннях.", "explSpecific": "Правильна відповідь тут — «К ослеплению встречных водителей». Інші варіанти в цьому питанні («Это может привести к сокращению срока службы батареи», «К возгоранию» та «К преждевременному износу ламп») не відповідають цій вимозі й тому неправильні."}, {"num": 678, "text": "Что из следующего водитель должен содержать в нормальном состоянии?", "topic": "Погодні умови та видимість", "options": ["Фары.", "Водительское удостоверение.", "Аварийные огни.", "Стеклоподъемник."], "correct": 0, "expl": "Фари — критично важливий елемент безпеки для видимості на дорозі, тому їхній справний стан водій повинен підтримувати особливо ретельно.", "explSpecific": "Правильно — «Фары». Водійське посвідчення, аварійні вогні (використовувані рідко) чи склопідйомник не мають такого ж прямого й постійного стосунку до безпеки під час кожної поїздки."}, {"num": 679, "text": "Что из следующего водитель должен содержать в нормальном состоянии?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Радио.", "Обивку.", "Ремни безопасности.", "Кузов."], "correct": 2, "expl": "Ремені безпеки — критично важливий елемент безпеки, тому їхній справний стан водій має підтримувати особливо ретельно, на відміну від суто комфортних елементів.", "explSpecific": "Правильно — «Ремни безопасности». Радіо, оббивка салону чи стан кузова важливі для комфорту чи естетики, але не мають прямого стосунку до життєво важливого захисту в разі аварії."}, {"num": 680, "text": "Какие альтернативы могут использовать водители для защиты окружающей среды?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Не использовать индикаторы при повороте.", "Использовать только низкие передачи.", "Использовать общественный транспорт.", "Резко ускоряться и тормозить во время вождения."], "correct": 2, "expl": "Та сама порада щодо захисту довкілля — користуватися громадським транспортом замість особистого автомобіля, коли це можливо.", "explSpecific": "Правильно — «Использовать общественный транспорт». Відмова від поворотників небезпечна й не має екологічного сенсу; їзда лише на низьких передачах чи різкі прискорення й гальмування підвищують витрату палива та шкідливі викиди."}, {"num": 681, "text": "Что должен сделать водитель перед буксировкой широкофюзеляжного прицепа?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Двигаться с красным флажком сзади слева от прицепа.", "Использовать дополнительные зеркала для наблюдения за другим транспортом.", "Двигаться с красным флажком спереди справа от прицепа.", "Ехать с постоянно мигающими аварийными огнями."], "correct": 1, "expl": "Перед буксируванням широкого причепа водій повинен встановити додаткові дзеркала, щоб компенсувати обмежений огляд ззаду та збоку.", "explSpecific": "Правильно — «Использовать дополнительные зеркала для наблюдения за другим транспортом». Червоний прапорець чи постійно мигаючі аварійні вогні — не є стандартною вимогою для широких причепів в Ірландії; додаткові дзеркала — реальна практична вимога."}, {"num": 682, "text": "Когда владелец удостоверения категории W может перевозить пассажира на тракторе или работающем транспортном средстве?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["При наличии надлежащего места для пассажира и наличии у пассажира полноценных водительских прав категории W.", "Если пассажир владеет полноценными водительскими правами категории М и персональной страховкой.", "Если пассажир владеет персональной страховкой.", "Если есть необходимость в их помощи."], "correct": 0, "expl": "Власник посвідчення категорії W може перевозити пасажира на тракторі чи робочому транспорті лише за умови наявності належного місця для пасажира і власного повного посвідчення категорії W у самого пасажира.", "explSpecific": "Правильно — «При наличии надлежащего места для пассажира и наличии у пассажира полноценных водительских прав категории W». Посвідчення категорії М, лише страховка чи «необхідність допомоги» не замінюють обов'язкову вимогу."}, {"num": 683, "text": "Что делать, если щетки стеклоочистителя не очищают ветровое стекло?", "topic": "Швидкісний режим", "options": ["Нанести пару капель масла на обе щетки стеклоочистителя.", "Согнуть рычаг стеклоочистителя, чтобы усилить давление на ветровое стекло.", "Заменить щетки как можно быстрее.", "Переключить рычаг управления стеклоочистителя с высокой скорости на низкую скорость несколько раз."], "correct": 2, "expl": "Якщо щітки склоочисника не очищують скло навіть на різних швидкостях, найправильніше рішення — якнайшвидше замінити самі щітки, які, ймовірно, зношені.", "explSpecific": "Правильно — «Заменить щетки как можно быстрее». Мастило на щітках чи згинання важеля для посилення тиску — неправильні й тимчасові «саморобні» рішення; перемикання швидкості щіток кілька разів не усуває причину — знос гумки."}, {"num": 684, "text": "Когда водителю следует использовать аварийные огни?", "topic": "Паркування та зупинка", "options": ["При стоянке на изгибе или в углу.", "При стоянке в неположенном месте, чтобы избежать штрафа.", "При поломке, которая делает ваш автомобиль препятствием для другого транспорта.", "При медленном движении."], "correct": 2, "expl": "Аварійні (сигнальні) вогні використовують, коли автомобіль створює несподівану перешкоду для іншого транспорту — наприклад, через поломку просто на проїжджій частині.", "explSpecific": "Правильно — «При поломке, которая делает ваш автомобиль препятствием для другого транспорта». «Стоянка на вигині чи в кутку» і «повільний рух» самі по собі не вимагають аварійних вогнів; «щоб уникнути штрафу за неправильну стоянку» — аварійні вогні не скасовують саму заборону чи штраф."}, {"num": 685, "text": "В каком порядке следует затягивать колесные гайки при замене колеса?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Сначала затяните по диагонали противоположные гайки.", "Сначала затяните по вертикали противоположные гайки.", "Сначала затяните по часовой стрелке противоположные гайки.", "Сначала затяните против часовой стрелки противоположные гайки."], "correct": 0, "expl": "Колісні гайки затягують у певній послідовності — навхрест (по діагоналі), а не по колу, щоб рівномірно притиснути колесо до маточини без перекосу.", "explSpecific": "Правильно — «Сначала затяните по диагонали противоположные гайки». Затягування по вертикалі чи послідовно по колу не забезпечує рівномірного притиснення й може призвести до перекосу диска."}, {"num": 686, "text": "Какую из следующих проверок должен выполнить водитель на своем автомобиле прежде чем тронуться с места?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Убедиться, что все окна авто надежно заперты.", "Убедиться, что коробка передач исправна.", "Убедитесь, что все двери надежно заперты.", "Убедиться, что кондиционер работает."], "correct": 2, "expl": "Перш ніж рушити з місця, водій повинен переконатися, що всі двері надійно зачинені, — це базова перевірка безпеки.", "explSpecific": "Правильно — «Убедитесь, что все двери надежно заперты». Вікна, коробка передач чи кондиціонер не є критичною передвиїзною перевіркою безпеки в тому ж сенсі, що зачинені двері."}, {"num": 687, "text": "Какой совет должен дать водитель пассажирам перед тем, как открыть дверь?", "topic": "Дитячі крісла та ремені безпеки", "options": ["Убедиться в наличии соответствующей защитной одежды", "Оглядеться и осторожно открыть дверь.", "Отстегнуть ремень безопасности и немедленно покинуть автомобиль.", "Оставить окна приоткрытыми, чтобы обеспечить циркуляцию воздуха."], "correct": 1, "expl": "Ремінь безпеки і дитяче крісло працюють за одним принципом — розподілити силу удару по найміцніших частинах тіла і не дати людині вилетіти з салону чи вдаритись об внутрішні поверхні авто. Відповідальність за пристібання дітей молодшого віку лежить на водієві, а не на самій дитині чи батьках, які не за кермом — це і пояснює логіку відповідей у таких питаннях.", "explSpecific": "Правильна відповідь тут — «Оглядеться и осторожно открыть дверь». Інші варіанти в цьому питанні («Убедиться в наличии соответствующей защитной одежды», «Отстегнуть ремень безопасности и немедленно покинуть автомобиль» та «Оставить окна приоткрытыми, чтобы обеспечить циркуляцию воздуха») не відповідають цій вимозі й тому неправильні."}, {"num": 688, "text": "Как убедиться, что ваш автомобиль припаркован безопасно?", "topic": "Паркування та зупинка", "options": ["Избегать неправильной парковки.", "Выехать на парковку как можно быстрее.", "Не парковаться, если такая парковка может подвергнуть опасности других участников дорожного движения.", "Припарковать транспортное средство напротив другого транспортного средства на узкой дороге."], "correct": 2, "expl": "Головне правило безпечної стоянки — не паркуватися там, де це може створити небезпеку для інших учасників дорожнього руху, незалежно від формальної відповідності розмітці.", "explSpecific": "Правильно — «Не парковаться, если такая парковка может подвергнуть опасности других участников дорожного движения». «Уникати неправильної парковки» — надто загальне й розпливчасте формулювання; поспішний виїзд на місце чи паркування навпроти іншого авто на вузькій дорозі — прямо небезпечні дії."}, {"num": 689, "text": "Что следует учитывать при движении задним ходом?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Смотреть по сторонам используя только зеркало заднего вида.", "Всегда быстро разворачиваться, чтобы выехать из пространства.", "Избегать включения заднего стеклоочистителя.", "Убедиться в отсутствии пешеходов и других транспортных средств вблизи."], "correct": 3, "expl": "Перш ніж рухатися заднім ходом, водій повинен переконатися у відсутності пішоходів і будь-якого іншого транспорту поблизу, а не покладатися лише на одне дзеркало.", "explSpecific": "Правильно — «Убедиться в отсутствии пешеходов и других транспортных средств вблизи». Використання лише дзеркала заднього виду залишає сліпі зони; швидкий розворот не має стосунку до безпеки самого маневру."}, {"num": 690, "text": "Кто несет ответственность за То, чтобы пассажир старше 17 лет использовал ремень безопасности во время поездки в автомобиле?", "topic": "Дитячі крісла та ремені безпеки", "options": ["Водитель, если пассажир находится на переднем сиденье.", "Только пассажир.", "Водитель и пассажир.", "Только водитель."], "correct": 1, "expl": "Ремінь безпеки і дитяче крісло працюють за одним принципом — розподілити силу удару по найміцніших частинах тіла і не дати людині вилетіти з салону чи вдаритись об внутрішні поверхні авто. Відповідальність за пристібання дітей молодшого віку лежить на водієві, а не на самій дитині чи батьках, які не за кермом — це і пояснює логіку відповідей у таких питаннях.", "explSpecific": "Правильна відповідь тут — «Только пассажир». Інші варіанти в цьому питанні («Водитель, если пассажир находится на переднем сиденье», «Водитель и пассажир» та «Только водитель») не відповідають цій вимозі й тому неправильні."}, {"num": 691, "text": "Следует ли перевозить ребенка, не закрепленного в детской удерживающей системе, на переднем пассажирском сиденье?", "topic": "Дитячі крісла та ремені безпеки", "options": ["Нет, если ребенок не использует детское сиденье.", "Да, при условии, что младенца надежно удерживает взрослый.", "Да, но только если на автомобиле установлены активные подушки безопасности.", "Нет, ребенок всегда должен быть зафиксирован в соответствующем детском кресле."], "correct": 3, "expl": "Ремінь безпеки і дитяче крісло працюють за одним принципом — розподілити силу удару по найміцніших частинах тіла і не дати людині вилетіти з салону чи вдаритись об внутрішні поверхні авто. Відповідальність за пристібання дітей молодшого віку лежить на водієві, а не на самій дитині чи батьках, які не за кермом — це і пояснює логіку відповідей у таких питаннях.", "explSpecific": "Правильна відповідь тут — «Нет, ребенок всегда должен быть зафиксирован в соответствующем детском кресле». Інші варіанти в цьому питанні («Нет, если ребенок не использует детское сиденье», «Да, при условии, что младенца надежно удерживает взрослый» та «Да, но только если на автомобиле установлены активные подушки безопасности») не відповідають цій вимозі й тому неправильні."}, {"num": 692, "text": "Что следует делать водителю при необходимости остановиться в чрезвычайной ситуации?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Переключиться в нейтральную передачу.", "Продолжительно нажимать на педаль сцепления.", "Продолжительно нажимать на педаль тормоза.", "Убедиться, что все двери надежно заперты."], "correct": 2, "expl": "В екстреній ситуації головне — продовжувати сильно й безперервно натискати на педаль гальма, щоб зупинити автомобіль максимально швидко.", "explSpecific": "Правильно — «Продолжительно нажимать на педаль тормоза». Перемикання в нейтраль чи тривале утримання зчеплення знімає гальмування двигуном і подовжує зупинку; перевірка дверей не має жодного стосунку до самої зупинки."}, {"num": 693, "text": "Что следует делать водителю при необходимости остановиться в чрезвычайной ситуации?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Нажать педаль тормоза и включите более высокую передачу.", "Отключить систему ABS.", "Нажать на тормоз.", "Нажать педаль сцепления и включить пониженную передачу."], "correct": 2, "expl": "В екстреній ситуації найпростіша й найефективніша дія — просто сильно натиснути на гальмо, довіряючи справним гальмам автомобіля.", "explSpecific": "Правильно — «Нажать на тормоз». Перемикання на вищу передачу чи вимкнення ABS під час екстреного гальмування погіршують результат; натискання зчеплення й пониження передачі знімає гальмування двигуном саме тоді, коли воно найбільш корисне."}, {"num": 694, "text": "Что должен делать водитель при смене колеса на своем автомобиле на дороге общего пользования?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Открыть передние двери.", "Открыть багажник.", "Поместите красный предупреждающий треугольник сбоку в задней части автомобиля.", "Поместите красный предупреждающий треугольник сбоку в передней части автомобиля."], "correct": 2, "expl": "Замінюючи колесо на дорозі загального користування, водій повинен встановити червоний попереджувальний трикутник позаду автомобіля збоку, щоб завчасно попередити транспорт, який наближається.", "explSpecific": "Правильно — «Поместите красный предупреждающий треугольник сбоку в задней части автомобиля». Трикутник спереду не попереджає транспорт, що наближається ЗЗАДУ — саме звідти йде основна небезпека."}, {"num": 695, "text": "Что нужно делать при замене колеса на дороге общего пользования, чтобы обеспечить собственную безопасность?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Убедиться, что установлена задняя передача, а передние колеса обращены к дороге.", "Убедиться, что установлена первая передача, а передние колеса обращены к дороге.", "Надеть светоотражающую одежду и включить аварийные огни.", "Попросить свидетеля предупредить другой транспорт, подавая ему сигнал стоя в середине дороги."], "correct": 2, "expl": "Заміна колеса на узбіччі дороги загального користування небезпечна через транспорт, що проїжджає повз, тому головне — бути максимально помітним: світловідбивний одяг і аварійні вогні.", "explSpecific": "Правильно — «Надеть светоотражающую одежду и включить аварийные огни». Вибір передачі й напрямку передніх коліс стосується зовсім іншої ситуації (стоянки на схилі); прохання свідка стояти посеред дороги, навпаки, наражає його на небезпеку."}, {"num": 696, "text": "В течение каких периодов времени водитель может проходить проверку на содержание наркотических веществ в крови на КПП на дороге?", "topic": "Дитячі крісла та ремені безпеки", "options": ["Только после ДТП.", "Только в дневное время.", "Только в ночное время.", "В любое время дня и ночи."], "correct": 3, "expl": "Ремінь безпеки і дитяче крісло працюють за одним принципом — розподілити силу удару по найміцніших частинах тіла і не дати людині вилетіти з салону чи вдаритись об внутрішні поверхні авто. Відповідальність за пристібання дітей молодшого віку лежить на водієві, а не на самій дитині чи батьках, які не за кермом — це і пояснює логіку відповідей у таких питаннях.", "explSpecific": "Правильна відповідь тут — «В любое время дня и ночи». Інші варіанти в цьому питанні («Только после ДТП», «Только в дневное время» та «Только в ночное время») не відповідають цій вимозі й тому неправильні."}, {"num": 697, "text": "Как должен действовать водитель при езде в густом тумане?", "topic": "Погодні умови та видимість", "options": ["Ехать с включёнными фарами ближнего света и противотуманными фарами.", "Ехать вдоль укрепленной части обочины и следить за отражающими маркерами.", "Снизить скорость и включить фары дальнего света.", "Ехать вдоль центральной разделительной линии и следить за отражающими маркерами."], "correct": 0, "expl": "У густому тумані оптимальна комбінація освітлення — фари ближнього світла разом із протитуманними фарами.", "explSpecific": "Правильно — «...ближнего света и противотуманными фарами». Габаритні вогні недостатньо яскраві; дальнє світло в тумані відбивається назад, засліплюючи самого водія; орієнтування по розмітці не є основною рекомендованою дією."}, {"num": 698, "text": "Что должен делать водитель, когда выезжает на подъездную дорогу с автомагистрали?", "topic": "Автомагістраль і тунелі", "options": ["Сильно тормозить при въезде на подъездную дорогу, чтобы замедлиться.", "Всегда постепенно снижать скорость на несколько километров.", "Никогда не нужно регулировать скорость на скользкой дороге.", "Строго соблюдайте ограничениям скорости."], "correct": 3, "expl": "З'їжджаючи з автомагістралі на під'їзну дорогу, водій повинен суворо дотримуватися обмеження швидкості нової дороги.", "explSpecific": "Правильно — «Строго соблюдайте ограничениям скорости». Різке гальмування на самому в'їзді, поступове зниження «на кілька кілометрів» чи ігнорування регулювання швидкості на слизькій дорозі — недоречні альтернативи."}, {"num": 699, "text": "Что из следующего должен сделать водитель перед въездом в туннель?", "topic": "Автомагістраль і тунелі", "options": ["Использовать только фары ближнего света, если другой транспорт находится в туннеле.", "Включить аварийные огни, чтобы предупредить другой транспорт о своем присутствии.", "Снять солнцезащитные очки если они одеты.", "Убедиться, что фары дальнего света включены."], "correct": 2, "expl": "Перед в'їздом у тунель, де освітлення різко змінюється, водій повинен зняти сонцезахисні окуляри, якщо вони на ньому, щоб не втратити видимість у темнішому просторі.", "explSpecific": "Правильно — «Снять солнцезащитные очки если они одеты». Використання лише ближнього світла умовно чи аварійні вогні без причини — недоречні дії; дальнє світло в тунелі засліплює зустрічний транспорт."}, {"num": 700, "text": "Что из следующего должен сделать водитель перед въездом в туннель?", "topic": "Автомагістраль і тунелі", "options": ["Включить аварийные огни, чтобы предупредить другой транспорт о своем присутствии.", "Использовать только фары ближнего света, если другой транспорт находится в туннеле.", "Убедиться, что фары дальнего света включены.", "Сохранять безопасное расстояние, от транспортного средства впереди вас."], "correct": 3, "expl": "Перед в'їздом у тунель водій повинен переконатися, що зберігає безпечну дистанцію до транспорту попереду, оскільки в тунелі різкі зупинки особливо небезпечні.", "explSpecific": "Правильно — «Сохранять безопасное расстояние, от транспортного средства впереди вас». Аварійні вогні без причини чи умовне ближнє світло — недоречні дії; дальнє світло в тунелі засліплює зустрічний транспорт."}, {"num": 701, "text": "Что должен делать водитель, если его транспортное средство выходит из строя или он попадает в аварию в туннеле?", "topic": "Автомагістраль і тунелі", "options": ["Подать сигнал другому транспорту о необходимости остановиться.", "Воспользоваться телефоном для экстренных случаев, чтобы вызвать подмогу.", "Выключить все огни и дожидаться помощи внутри автомобиля.", "Подать сигнал другому транспорту о возможности обгона."], "correct": 1, "expl": "Якщо транспортний засіб вийшов з ладу чи потрапив в аварію в тунелі, водій повинен скористатися екстреним телефоном для виклику допомоги.", "explSpecific": "Правильно — «Воспользоваться телефоном для экстренных случаев, чтобы вызвать подмогу». Сигналізація іншим про потребу зупинитися не вирішує власну проблему; очікування допомоги всередині авто з вимкненими вогнями небезпечне."}, {"num": 702, "text": "Что должен делать водитель, если его транспортное средство выходит из строя или он попадает в аварию в туннеле?", "topic": "Автомагістраль і тунелі", "options": ["Выключить все огни и дожидаться помощи внутри автомобиля.", "Подать сигнал другому транспорту о необходимости остановиться.", "Включить аварийный сигнал и остановиться так близко к левой стороне насколько это возможно", "Подать сигнал другому транспорту о возможности обгона."], "correct": 2, "expl": "У разі несправності чи аварії в тунелі водій повинен увімкнути аварійну сигналізацію і зупинитися якомога ближче до лівого краю, звільняючи простір для проїзду й аварійних служб.", "explSpecific": "Правильно — «Включить аварийный сигнал и остановиться так близко к левой стороне насколько это возможно». Очікування всередині авто з вимкненими вогнями небезпечне; сигналізація про можливість обгону не є першочерговою дією."}, {"num": 703, "text": "Что должен делать водитель, когда он видит впереди медленно движущееся транспортное средство, управляемое водителем-учеником?", "topic": "Обгін та зміна смуги руху", "options": ["Быть терпеливым и при необходимости дать водителю больше времени.", "Обогнать его как можно быстрее.", "Подъехать ближе к автомобилю, чтобы водитель ехал быстрее.", "Подъехать ближе к автомобилю, чтобы сообщить о своем намерение совершить обгон."], "correct": 0, "expl": "Позаду повільного учнівського водія головне правило — терпіння: дати йому більше часу і не тиснути психологічно.", "explSpecific": "Правильно — «Быть терпеливым и при необходимости дать водителю больше времени». Спроба обігнати якнайшвидше без оцінки безпеки чи наближення впритул — небезпечні й неввічливі дії."}, {"num": 704, "text": "На перекрестках какой тип участников дорожного движения особенно уязвим?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Мотоциклисты.", "Водители транспортных средств.", "Водители тракторов.", "Водители грузовиков."], "correct": 0, "expl": "Аналогічно — на перехрестях особливо вразливі мотоциклісти, оскільки вони менш помітні для інших водіїв і не мають захисту кузова.", "explSpecific": "Правильно — «Мотоциклисты». Водії транспортних засобів, тракторів чи вантажівок перебувають у захищеному кузові й менш вразливі, ніж мотоциклісти."}, {"num": 705, "text": "На перекрестках какой тип участников дорожного движения особенно уязвим?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Водители транспортных средств.", "Водители тракторов.", "Велосипедисты.", "Водители грузовиков."], "correct": 2, "expl": "Так само вразливими на перехрестях є велосипедисти — вони менш помітні й не захищені кузовом транспортного засобу.", "explSpecific": "Правильно — «Велосипедисты». Водії транспортних засобів, тракторів чи вантажівок перебувають у захищеному кузові й менш вразливі, ніж велосипедисти."}, {"num": 706, "text": "На каких участников дорожного движения, появляющихся с левой стороны, водитель должен обращать особое внимание стоя на светофоре?", "topic": "Дорожні знаки та розмітка", "options": ["Фургоны.", "Автомобили.", "Велосипедисты.", "Тракторы."], "correct": 2, "expl": "Той самий принцип підвищеної уваги до вразливих учасників зліва на світлофорі.", "explSpecific": "Правильно — «Велосипедисты», з тих самих причин: вузький силует і менша помітність роблять велосипедистів пріоритетною категорією уваги порівняно з фургонами, автомобілями чи тракторами."}, {"num": 707, "text": "Что должен делать водитель, когда собирается повернуть налево на оживленном перекрестке, и вокруг него находятся пешеходы и велосипедисты?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Держаться ближе к левому краю, чтобы велосипедисты или пешеходы не могли подъехать с левой стороны.", "Держаться правее, чтобы освободить место для велосипедистов.", "Включить левый поворот, посмотреть в правое зеркало и сделать поворот, когда дорога освободится.", "Оставить достаточно места для пешеходов, слева."], "correct": 3, "expl": "Повертаючи ліворуч на оживленому перехресті серед пішоходів і велосипедистів, водій повинен залишити достатньо простору для пішоходів зліва, а не притискатися до краю.", "explSpecific": "Правильно — «Оставить достаточно места для пешеходов, слева». Утримання лівого краю, щоб «блокувати» велосипедистів чи пішоходів, — небезпечна дія; зміщення праворуч не вирішує потреби залишити місце пішоходам зліва."}, {"num": 708, "text": "Что должен делать водитель, когда собирается повернуть налево на оживленном перекрестке, и вокруг него находятся пешеходы и велосипедисты?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Держаться ближе к левому краю, чтобы велосипедисты или пешеходы не могли подъехать с левой стороны.", "Включить левый поворот, посмотреть в правое зеркало и сделать поворот, когда дорога освободится.", "Обратить внимание на велосипедистов и пешеходов с левой стороны.", "Держаться правее, чтобы освободить место для велосипедистов."], "correct": 2, "expl": "Той самий маневр повороту ліворуч серед пішоходів і велосипедистів — головне правило: звертати увагу саме на тих, хто зліва, з боку повороту.", "explSpecific": "Правильно — «Обратить внимание на велосипедистов и пешеходов с левой стороны». Утримання лівого краю, щоб їх «заблокувати», чи зміщення праворуч не замінюють потреби активно стежити за учасниками руху саме зліва."}, {"num": 709, "text": "На присутствие каких участников дорожного движения водитель должен периодически проверять свои слепые зоны в медленном городском потоке.", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Фургонов.", "Такси.", "Пешеходов.", "Автомобилей."], "correct": 2, "expl": "У повільному міському потоці пішоходи — найвразливіші й водночас найлегше непомітні учасники руху в сліпих зонах.", "explSpecific": "Правильно — «Пешеходов». Фургони, таксі й автомобілі — самі транспортні засоби з певним захистом, тоді як пішохід повністю незахищений і менш помітний у сліпій зоні."}, {"num": 710, "text": "На присутствие каких участников дорожного движения водитель должен периодически проверять свои слепые зоны в медленном городском потоке.", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Автомобилей.", "Такси.", "Фургонов.", "Мотоциклистов."], "correct": 3, "expl": "У повільному міському потоці мотоциклісти — вузькі й легко непомітні в сліпих зонах учасники руху, яких водій повинен періодично перевіряти.", "explSpecific": "Правильно — «Мотоциклистов». Автомобілі, таксі й фургони мають значно більший силует і легше помітні порівняно з вузьким профілем мотоцикла."}, {"num": 711, "text": "Кто из следующих участников дорожного движения наиболее уязвим в медленном городском потоке?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Автомобили.", "Такси.", "Мотоциклисты.", "Фургоны."], "correct": 2, "expl": "У повільному міському потоці мотоциклісти — одні з найвразливіших учасників руху, оскільки мають мінімальний фізичний захист порівняно з автомобілем.", "explSpecific": "Правильно — «Мотоциклисты». Автомобілі, таксі й фургони забезпечують водієві й пасажирам значний фізичний захист кузова, якого мотоцикліст позбавлений."}, {"num": 712, "text": "Что должен делать водитель во время движения ночью по неосвещенной дороге?", "topic": "Погодні умови та видимість", "options": ["Ехать по центру дороги.", "Остерегаться бродячих и домашних животных.", "Двигаться левее, чтобы избежать встречного движения.", "Подъехать как можно ближе к отражающей линии."], "correct": 1, "expl": "На неосвітленій дорозі вночі одна з головних прихованих небезпек — поява бродячих чи домашніх тварин, яких важко вчасно помітити в темряві.", "explSpecific": "Правильно — «Остерегаться бродячих и домашних животных». Рух по центру дороги чи ліворуч «щоб уникнути зустрічного руху» — небезпечні маневри."}, {"num": 713, "text": "Что должен делать водитель во время движения ночью по неосвещенной дороге?", "topic": "Паркування та зупинка", "options": ["Обратить внимание на припаркованные автомобили слева.", "Двигаться левее, чтобы избежать встречного движения.", "Ехать по центру дороги.", "Подъехать как можно ближе к отражающей линии."], "correct": 0, "expl": "На неосвітленій дорозі вночі водій повинен звертати увагу на припарковані зліва автомобілі, які можуть бути погано помітні без освітлення.", "explSpecific": "Правильно — «Обратить внимание на припаркованные автомобили слева». Зміщення ліворуч «щоб уникнути зустрічного руху» чи рух по центру дороги — небезпечні маневри; наближення до відбивної лінії не є основною рекомендованою тактикою."}, {"num": 714, "text": "О чем должен знать водитель при движении зимой в темное время по утрам и вечерам по неосвещенным проселочным дорогам?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Водитель должен постоянно ездить с включенными габаритными фонарями, чтобы иметь возможность видеть пешеходов, идущих по неосвещенным проселочным дорогам.", "О том, что отсутствие света не повлияет на способность водителя видеть бездомных животных на дороге.", "Водитель должен ожидать, что пешеходы окажутся на тротуаре и не будут подвергнуты опасности столкновения.", "Велосипедисты гораздо более уязвимы в условиях плохого освещения."], "correct": 3, "expl": "Взимку темними ранками й вечорами на неосвітлених путівцевих дорогах велосипедисти особливо вразливі через погану видимість і власну незахищеність.", "explSpecific": "Правильно — «Велосипедисты гораздо более уязвимы в условиях плохого освещения». Постійне увімкнення лише габаритів недостатньо; впевненість, що пішоходи будуть на тротуарі, — недбале припущення."}, {"num": 715, "text": "На что может повлиять вождение на недостаточно накачанных шинах?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Система климат-контроля.", "Температура двигателя.", "Выхлопная система.", "Расход горючего."], "correct": 3, "expl": "Недостатньо накачані шини гірше тримають контакт з дорогою і мають вищий опір коченню, через що зростає саме витрата пального.", "explSpecific": "Правильно — «Расход горючего». Клімат-контроль, температура двигуна чи вихлопна система фізично не пов'язані з тиском у шинах."}, {"num": 716, "text": "Как водитель может помочь окружающей среде?", "topic": "Швидкісний режим", "options": ["Путем повышения скорости.", "Путем резкого торможения.", "Наблюдать за дорогой и планировать наперёд.", "Путем резкого ускорения."], "correct": 2, "expl": "Спостереження за дорогою і завчасне прогнозування ситуації дозволяють уникати різких прискорень і гальмувань, що допомагає довкіллю.", "explSpecific": "Правильно — «Наблюдать за дорогой и планировать наперёд». Підвищення швидкості чи різке гальмування й прискорення, навпаки, шкодять довкіллю через підвищену витрату палива."}, {"num": 717, "text": "Чего можно достигнуть за счет эко-вождения?", "topic": "Дитячі крісла та ремені безпеки", "options": ["Увеличение времени в пути.", "Сокращение времени в пути.", "Уменьшение выброса выхлопных газов.", "Увеличение потребления топлива."], "correct": 2, "expl": "Ремінь безпеки і дитяче крісло працюють за одним принципом — розподілити силу удару по найміцніших частинах тіла і не дати людині вилетіти з салону чи вдаритись об внутрішні поверхні авто. Відповідальність за пристібання дітей молодшого віку лежить на водієві, а не на самій дитині чи батьках, які не за кермом — це і пояснює логіку відповідей у таких питаннях.", "explSpecific": "Правильна відповідь тут — «Уменьшение выброса выхлопных газов». Інші варіанти в цьому питанні («Увеличение времени в пути», «Сокращение времени в пути» та «Увеличение потребления топлива») не відповідають цій вимозі й тому неправильні."}, {"num": 718, "text": "Чего можно достигнуть за счет эко-вождения?", "topic": "Дитячі крісла та ремені безпеки", "options": ["Увеличение времени в пути.", "Сокращение времени в пути.", "Увеличение потребления топлива.", "Повышение дорожной безопасности."], "correct": 3, "expl": "Ремінь безпеки і дитяче крісло працюють за одним принципом — розподілити силу удару по найміцніших частинах тіла і не дати людині вилетіти з салону чи вдаритись об внутрішні поверхні авто. Відповідальність за пристібання дітей молодшого віку лежить на водієві, а не на самій дитині чи батьках, які не за кермом — це і пояснює логіку відповідей у таких питаннях.", "explSpecific": "Правильна відповідь тут — «Повышение дорожной безопасности». Інші варіанти в цьому питанні («Увеличение времени в пути», «Сокращение времени в пути» та «Увеличение потребления топлива») не відповідають цій вимозі й тому неправильні."}, {"num": 719, "text": "Что способствует эко-вождению?", "topic": "Швидкісний режим", "options": ["Предвидение и наблюдение.", "Монтаж багажника на крыше.", "Вождение на пониженной передаче на высокой скорости.", "Резкое торможение."], "correct": 0, "expl": "Економічному водінню сприяє передбачення дорожньої ситуації та постійне спостереження, що дозволяє уникати різких, неекономних маневрів.", "explSpecific": "Правильно — «Предвидение и наблюдение». Багажник на даху погіршує аеродинаміку; їзда на пониженій передачі на високій швидкості й різке гальмування — неекономні звички."}, {"num": 720, "text": "Что способствует эко-вождению?", "topic": "Швидкісний режим", "options": ["Вождение на пониженной передаче на высокой скорости.", "Монтаж багажника на крыше.", "Резкое торможение.", "Соблюдение постоянной скорости."], "correct": 3, "expl": "Підтримання сталої швидкості без зайвих прискорень і гальмувань — один з основних принципів економічного водіння.", "explSpecific": "Правильно — «Соблюдение постоянной скорости». Багажник на даху погіршує аеродинаміку; їзда на пониженій передачі на високій швидкості й різке гальмування — неекономні звички, що підвищують витрату палива."}, {"num": 721, "text": "Что может привести к заносу автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Использование резкого ускорение.", "Выбег до остановки.", "Контролируемое ускорение.", "Остановка на четвертой передаче."], "correct": 0, "expl": "Різке, надмірно різке прискорення може спричинити пробуксовку та втрату зчеплення ведучих коліс, що є одним з поширених сценаріїв заносу.", "explSpecific": "Правильно — «Использование резкого ускорение». Контрольоване прискорення чи виважений накат до зупинки не спричиняють заносу; зупинка на високій передачі — незручна, але сама по собі не викликає занос."}, {"num": 722, "text": "Что может привести к заносу автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Контролируемое ускорение.", "Выбег до остановки.", "Остановка на четвертой передаче.", "Чрезмерная скорость."], "correct": 3, "expl": "Надмірна швидкість зменшує запас часу й простору для реакції на будь-яку несподіванку, і саме вона є одним з головних факторів ризику заносу.", "explSpecific": "Правильно — «Чрезмерная скорость». Контрольоване прискорення чи накат до зупинки безпечні самі по собі; зупинка на високій передачі незручна, але не провокує занос."}, {"num": 723, "text": "Какое транспортное средство освобождается от ограничений скорости при использовании в чрезвычайной ситуации?", "topic": "Швидкісний режим", "options": ["Доктор по вызову.", "Горная спасательная служба.", "Службы скорой помощи.", "Служба аварийного восстановления."], "correct": 2, "expl": "Від обмежень швидкості в надзвичайній ситуації звільняються служби швидкої медичної допомоги під час термінового виїзду.", "explSpecific": "Правильно — «Службы скорой помощи». Виклик лікаря, гірська рятувальна служба чи служба аварійного відновлення не входять до переліку служб, звільнених від обмежень швидкості, у цьому варіанті питання."}, {"num": 724, "text": "Какое транспортное средство освобождается от ограничений скорости при использовании в чрезвычайной ситуации?", "topic": "Швидкісний режим", "options": ["Служба аварийного восстановления.", "Горная спасательная служба.", "Доктор по вызову.", "Гарда (Полиция)"], "correct": 3, "expl": "Від обмежень швидкості в надзвичайній ситуації звільняється поліція (Гарда) під час термінового виїзду за службовою потребою.", "explSpecific": "Правильно — «Гарда (Полиция)». Служба аварійного відновлення, гірська рятувальна служба чи виклик лікаря не входять до переліку служб, звільнених від обмежень швидкості, у цьому варіанті питання."}, {"num": 725, "text": "Чем опасно движение по плохо освещенной улице?", "topic": "Дорожні знаки та розмітка", "options": ["Водители могут видеть только встречный транспорт.", "Пешеходы, переходящие дорогу в неосвещённом (тёмном) месте.", "Водители могут видеть только транспорт, движущийся перед ними.", "Светофор не будет работать."], "correct": 1, "expl": "На погано освітленій вулиці небезпека стосується не лише транспорту, а й пішоходів, яких особливо важко помітити, коли вони переходять дорогу в темному, неосвітленому місці.", "explSpecific": "Правильно — «Пешеходы, переходящие дорогу в неосвещённом (тёмном) месте». «Бачити лише зустрічний/передній транспорт» звужують проблему до транспорту; «світлофор не працюватиме» не пов'язаний із освітленням вулиці як таким.", "img": "q725.png"}, {"num": 726, "text": "Водитель намерен повернуть направо на этом перекрестке. Как он может это сделать?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Продолжить движение перед мотоциклом и автобусом.", "Остановиться перед мотоциклом.", "Остановиться перед автобусом.", "Продолжить движение после того, как проехали мотоцикл и автобус."], "correct": 3, "expl": "Після обов'язкової зупинки на знаку STOP водій повинен пропустити мотоцикл і автобус, які вже рухаються перехрестям, і продовжити рух лише після того, як вони проїдуть.", "explSpecific": "Правильно — «Продолжить движение после того, как проехали мотоцикл и автобус». Проїзд перед обома транспортними засобами чи зупинка лише перед одним з них (мотоциклом чи автобусом) — небезпечні або неповні дії, що ігнорують одного з двох учасників.", "img": "q726.png"}, {"num": 727, "text": "Намереваясь повернуть направо, как показано на рисунке, что должен делать водитель автомобиля?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Продолжите и дайте грузовику проехать первым.", "Продолжите и дайте грузовику и встречному автомобилю проехать первыми.", "Проехать перед грузовиком.", "Осторожно продолжайте движение, поскольку у вас преимущество."], "correct": 2, "expl": "У цій ситуації водій, повертаючи праворуч, має чіткий пріоритет і достатньо простору, щоб проїхати попереду вантажівки, не створюючи перешкод.", "explSpecific": "Правильно — «Проехать перед грузовиком». Очікування, поки проїдуть вантажівка чи зустрічний автомобіль, не потрібне за цих умов; надто узагальнене «обережно продовжуйте, оскільки у вас перевага» не описує конкретну дію.", "img": "q727.png"}, {"num": 728, "text": "Какая опасность может ожидать вас за вершиной холма?", "topic": "Обгін та зміна смуги руху", "options": ["Обрыв дороги.", "Встречное транспортное средство может частично ехать по вашей полосе.", "Озеро.", "Железнодорожный переезд."], "correct": 1, "expl": "Той самий принцип обмеженої видимості за вершиною пагорба — у цьому варіанті прихованою небезпекою позначено зустрічний транспорт, що частково заїжджає на вашу смугу.", "explSpecific": "Правильно — «Встречное транспортное средство может частично ехать по вашей полосе». «Обрив дороги», «озеро» і «залізничний переїзд» — відповіді на суміжні варіанти цієї ж серії питань.", "img": "q728.png"}, {"num": 729, "text": "Какая опасность может ожидать вас за вершиной холма?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Озеро", "Железнодорожный переезд.", "Впереди может быть сломанный автомобиль.", "Обрыв дороги."], "correct": 2, "expl": "За вершиною пагорба видимість дороги попереду різко обмежена, тому там може ховатися будь-яка несподівана перешкода — у цьому конкретному варіанті питання це поламаний автомобіль.", "explSpecific": "Правильно — «Впереди может быть сломанный автомобиль» — саме цей варіант позначено як очікувану небезпеку в цьому питанні. «Озеро», «залізничний переїзд» і «обрив дороги» — відповіді на суміжні варіанти цієї ж серії питань.", "img": "q729.png"}, {"num": 730, "text": "Какая опасность может ожидать вас за вершиной холма?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Железнодорожный переезд.", "Озеро.", "Обрыв дороги.", "Пешеходы могут идти вам навстречу."], "correct": 3, "expl": "За вершиною пагорба видимість дороги попереду різко обмежена — у цьому варіанті прихованою небезпекою позначені пішоходи, що йдуть назустріч.", "explSpecific": "Правильно — «Пешеходы могут идти вам навстречу». «Залізничний переїзд», «озеро» і «обрив дороги» — відповіді на суміжні варіанти цієї ж серії питань.", "img": "q730.png"}, {"num": 731, "text": "Какая опасность может ожидать вас за вершиной холма?", "topic": "Загальні правила та поведінка на дорозі", "options": ["На дороге может появиться домашний скот.", "Железнодорожный переезд.", "Озеро.", "Обрыв дороги."], "correct": 0, "expl": "Той самий принцип обмеженої видимості за вершиною пагорба — у цьому варіанті питання прихованою небезпекою позначена домашня худоба на дорозі.", "explSpecific": "Правильно — «На дороге может появиться домашний скот». «Залізничний переїзд», «озеро» і «обрив дороги» — відповіді на суміжні варіанти цієї ж серії питань.", "img": "q731.png"}, {"num": 732, "text": "Какая опасность может ожидать вас за вершиной холма?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Железнодорожный переезд.", "Там могут проводиться работы по стрижке зеленых насаждений.", "Обрыв дороги.", "Озеро."], "correct": 1, "expl": "Той самий принцип обмеженої видимості за вершиною пагорба — цього разу прихованою небезпекою позначено роботи з підрізки зелених насаджень на узбіччі.", "explSpecific": "Правильно — «Там могут проводиться работы по стрижке зеленых насаждений». «Залізничний переїзд», «обрив дороги» і «озеро» — відповіді на суміжні варіанти цієї серії.", "img": "q732.png"}, {"num": 733, "text": "О чем должен знать водитель, следуя за мотоциклистом, при том, что белый автомобиль выезжает задним ходом на дорогу?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Мотоциклист может внезапно затормозить.", "Водитель на автомобиле, дающий задний ход, остановиться, когда увидит мотоциклиста.", "Стоп-сигналы на мотоцикле могут не работать.", "Мотоциклист может дать сигнал водителю, дающему задний ход, о необходимости остановиться."], "correct": 0, "expl": "Слідуючи за мотоциклістом у ситуації, коли попереду інший автомобіль здає заднім ходом, водій повинен пам'ятати, що мотоцикліст може раптово й різко загальмувати.", "explSpecific": "Правильно — «Мотоциклист может внезапно затормозить». Обов'язок водія заднього ходу зупинитися чи несправність стоп-сигналів мотоцикла — це дії чи стан інших учасників, а не пряма небезпека для водія за мотоциклом.", "img": "q733.png"}, {"num": 734, "text": "Почему после сильного ливня водитель должен находиться на большем расстоянии от автомобиля, едущего впереди?", "topic": "Погодні умови та видимість", "options": ["Потому что после дождя колеса вращаются с большой скоростью.", "Потому что после дождя колеса возвращаются с меньшей скоростью.", "Потому что брызги из-под колес могут ухудшить видимость.", "Потому что сцепление с дорогой улучшается при намокании."], "correct": 2, "expl": "Після сильної зливи бризки з-під коліс транспорту попереду можуть різко погіршити видимість, тому потрібна більша дистанція, щоб встигнути відреагувати.", "explSpecific": "Правильно — «Потому что брызги из-под колес могут ухудшить видимость». Твердження про зміну швидкості обертання коліс чи покращення зчеплення при намоканні — фізично необґрунтовані вигадки.", "img": "q734.png"}, {"num": 735, "text": "К чему должен быть готов водитель на этой улице с односторонним движением с припаркованными с обеих сторон транспортными средствами?", "topic": "Обгін та зміна смуги руху", "options": ["Встречному движению, когда водитель обгоняет грузовик.", "У грузовика может быть левостороннее управление.", "На грузовике может не быть правильной маркировки.", "Может открыться дверь автомобиля с любой из сторон улицы."], "correct": 3, "expl": "На вузькій односторонній вулиці з припаркованими з обох боків автомобілями головна прихована небезпека — раптово відчинені двері будь-якого припаркованого авто.", "explSpecific": "Правильно — «Может открыться дверь автомобиля с любой из сторон улицы». Зустрічний рух неможливий на односторонній вулиці; твердження про кермо праворуч чи неправильне маркування вантажівки — вигадані деталі.", "img": "q735.png"}]);
